{
  "name": "LuminaSpec AI",
  "description": "An intelligent specification assistant for home automation integrators. Generates precise Bills of Materials (BOM) from project requirements using Gemini AI."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum DeviceType {
  LIGHT_DIM = 'LIGHT_DIM',
  LIGHT_ONOFF = 'LIGHT_ONOFF',
  LIGHT_RGB = 'LIGHT_RGB',
  CURTAIN_ROLLER = 'CURTAIN_ROLLER',
  CURTAIN_DRAPERY = 'CURTAIN_DRAPERY',
  AC_SPLIT = 'AC_SPLIT',
  AC_CENTRAL = 'AC_CENTRAL',
}

export interface ProjectInputs {
  projectName: string;
  integratorName: string;
  counts: Record<DeviceType, number>;
}

export interface BomItem {
  sku: string;
  name: string;
  description: string;
  quantity: number;
  category: 'Controller' | 'Lighting' | 'Shading' | 'Climate' | 'Accessory';
  reasoning?: string;
}

export interface SpecificationResult {
  items: BomItem[];
  totalDevices: number;
  summary: string;
}

export const DEVICE_LABELS: Record<DeviceType, string> = {
  [DeviceType.LIGHT_DIM]: 'Circuitos Dimerizáveis',
  [DeviceType.LIGHT_ONOFF]: 'Circuitos On/Off (Relé)',
  [DeviceType.LIGHT_RGB]: 'Fitas LED RGB/RGBW',
  [DeviceType.CURTAIN_ROLLER]: 'Persianas Rolo (Motor Tubular)',
  [DeviceType.CURTAIN_DRAPERY]: 'Cortinas de Trilho (Abertura Central/Lateral)',
  [DeviceType.AC_SPLIT]: 'Ar Condicionado Split (IR)',
  [DeviceType.AC_CENTRAL]: 'Ar Condicionado Central (Termostato)',
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ProjectInputs, SpecificationResult } from "../types";

// Define the fictitious catalog logic in the system prompt
const CATALOG_SYSTEM_PROMPT = `
You are an expert Automation Specification Engineer for a brand called "LuminaSmart".
Your goal is to analyze project requirements and generate a Bill of Materials (BOM) using ONLY the products below.

## LuminaSmart Product Catalog

1. **Processors (Brain)**
   - SKU: LMS-HUB-PRO
     - Name: Lumina Processor Pro
     - Rule: Exactly 1 required per project. Handles up to 200 devices.

2. **Lighting Control**
   - SKU: LMS-DIM-4
     - Name: 4-Channel Dimmer Module (DIN)
     - Capacity: 4 dimmable circuits per module.
   - SKU: LMS-REL-8
     - Name: 8-Channel Relay Module (DIN)
     - Capacity: 8 on/off circuits per module.
   - SKU: LMS-DMX-GW
     - Name: DMX RGB Gateway
     - Capacity: Controls up to 32 RGB fixtures/strips via DMX. One is usually enough for residential RGB needs unless quantity > 32.

3. **Shading Control**
   - SKU: LMS-MOT-2
     - Name: Dual Motor Controller
     - Capacity: Controls 2 standard AC motors (Roller or Drapery).

4. **Climate Control**
   - SKU: LMS-IR-360
     - Name: 360 IR Blaster
     - Capacity: 1 required per Split AC unit (must have line of sight, assume 1 per split).
   - SKU: LMS-THERM-W
     - Name: Wall Smart Thermostat
     - Capacity: 1 required per Central AC zone.

## Logic Rules
- Calculate the minimum number of modules needed to cover the requested circuits.
- Example: 5 dimmable circuits -> Needs 2x LMS-DIM-4 (Capacity 4+4=8).
- Example: 10 dimmable circuits -> Needs 3x LMS-DIM-4 (Capacity 4+4+4=12).
- Example: 3 Roller Blinds -> Needs 2x LMS-MOT-2 (Capacity 2+2=4).
- Always output a brief 'reasoning' for each line item explaining the math (e.g., "5 circuits require 2 modules of 4 channels").
`;

const RESPONSE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    items: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          sku: { type: Type.STRING },
          name: { type: Type.STRING },
          description: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Controller', 'Lighting', 'Shading', 'Climate', 'Accessory'] },
          quantity: { type: Type.INTEGER },
          reasoning: { type: Type.STRING },
        },
        required: ['sku', 'name', 'category', 'quantity', 'reasoning'],
      },
    },
    totalDevices: { type: Type.INTEGER, description: "Total count of physical devices controlled" },
    summary: { type: Type.STRING, description: "A professional executive summary of the system designed." },
  },
  required: ['items', 'totalDevices', 'summary'],
};

export const generateSpecification = async (inputs: ProjectInputs): Promise<SpecificationResult> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please set process.env.API_KEY.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Filter out zero counts to keep the prompt clean
  const activeInputs = Object.entries(inputs.counts)
    .filter(([_, count]) => count > 0)
    .map(([key, count]) => `${key}: ${count}`)
    .join('\n');

  if (!activeInputs) {
    throw new Error("No devices selected.");
  }

  const prompt = `
    Project Name: ${inputs.projectName}
    Integrator: ${inputs.integratorName}

    Requested Devices:
    ${activeInputs}

    Please generate the LuminaSmart specification.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: CATALOG_SYSTEM_PROMPT,
        responseMimeType: 'application/json',
        responseSchema: RESPONSE_SCHEMA,
        temperature: 0.2, // Low temperature for deterministic math
      },
    });

    if (response.text) {
      return JSON.parse(response.text) as SpecificationResult;
    }
    throw new Error("No response generated.");
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React from 'react';
import { Plus, Minus } from 'lucide-react';

interface CounterInputProps {
  label: string;
  value: number;
  onChange: (val: number) => void;
  icon?: React.ReactNode;
}

export const CounterInput: React.FC<CounterInputProps> = ({ label, value, onChange, icon }) => {
  const handleIncrement = () => onChange(value + 1);
  const handleDecrement = () => onChange(Math.max(0, value - 1));

  return (
    <div className="flex items-center justify-between p-4 bg-white border border-slate-200 rounded-lg shadow-sm hover:border-brand-500 transition-colors">
      <div className="flex items-center gap-3">
        {icon && <div className="text-brand-600">{icon}</div>}
        <span className="font-medium text-slate-700">{label}</span>
      </div>
      <div className="flex items-center gap-3">
        <button
          onClick={handleDecrement}
          disabled={value === 0}
          className="p-1 rounded-full hover:bg-slate-100 disabled:opacity-30 text-slate-500 transition-colors"
          type="button"
        >
          <Minus size={20} />
        </button>
        <span className="w-8 text-center font-bold text-lg text-slate-900">{value}</span>
        <button
          onClick={handleIncrement}
          className="p-1 rounded-full hover:bg-brand-50 text-brand-600 transition-colors"
          type="button"
        >
          <Plus size={20} />
        </button>
      </div>
    </div>
  );
};

import React from 'react';
import { SpecificationResult, BomItem } from '../types';
import { FileText, CheckCircle2, Package, Cpu, Lightbulb, Blinds, Thermometer, Download } from 'lucide-react';

interface ResultViewProps {
  data: SpecificationResult;
  onReset: () => void;
}

const CategoryIcon: React.FC<{ category: string }> = ({ category }) => {
  switch (category) {
    case 'Controller': return <Cpu className="text-purple-600" />;
    case 'Lighting': return <Lightbulb className="text-yellow-600" />;
    case 'Shading': return <Blinds className="text-blue-600" />;
    case 'Climate': return <Thermometer className="text-red-600" />;
    default: return <Package className="text-slate-600" />;
  }
};

export const ResultView: React.FC<ResultViewProps> = ({ data, onReset }) => {
