import React, { useState } from 'react';
import { ProjectInputs, DeviceType, DEVICE_LABELS, SpecificationResult } from './types';
import { CounterInput } from './components/CounterInput';
import { generateSpecification } from './services/geminiService';
import { ResultView } from './components/ResultView';
import { 
  Lightbulb, 
  Blinds, 
  Thermometer, 
  Zap, 
  ArrowRight, 
  Loader2, 
  LayoutTemplate 
} from 'lucide-react';

const INITIAL_STATE: ProjectInputs = {
  projectName: '',
  integratorName: '',
  counts: {
    [DeviceType.LIGHT_DIM]: 0,
    [DeviceType.LIGHT_ONOFF]: 0,
    [DeviceType.LIGHT_RGB]: 0,
    [DeviceType.CURTAIN_ROLLER]: 0,
    [DeviceType.CURTAIN_DRAPERY]: 0,
    [DeviceType.AC_SPLIT]: 0,
    [DeviceType.AC_CENTRAL]: 0,
  }
};

const App: React.FC = () => {
  const [inputs, setInputs] = useState<ProjectInputs>(INITIAL_STATE);
  const [result, setResult] = useState<SpecificationResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleCountChange = (type: DeviceType, val: number) => {
    setInputs(prev => ({
      ...prev,
      counts: { ...prev.counts, [type]: val }
    }));
  };

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setInputs(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const spec = await generateSpecification(inputs);
      setResult(spec);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Ocorreu um erro desconhecido.");
    } finally {
      setLoading(false);
    }
  };

  const totalDevices = Object.values(inputs.counts).reduce((a, b) => a + b, 0);

  return (
    <div className="min-h-screen pb-12">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-brand-600 p-2 rounded-lg text-white">
              <Zap size={20} fill="currentColor" />
            </div>
            <h1 className="font-bold text-xl text-slate-800 tracking-tight">
              LuminaSpec <span className="text-brand-600 font-light">AI</span>
            </h1>
          </div>
          <div className="text-xs font-medium text-slate-400 uppercase tracking-wider hidden sm:block">
            Ferramenta para Integradores
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 mt-8">

        {result ? (
          <ResultView data={result} onReset={() => setResult(null)} />
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-fade-in">
            {/* Left Col: Introduction */}
            <div className="lg:col-span-1 space-y-6">
              <div>
                <h2 className="text-2xl font-bold text-slate-900 mb-2">Novo Projeto</h2>
                <p className="text-slate-600">
                  Insira os detalhes do projeto e as quantidades de dispositivos. Nossa IA calculará a infraestrutura necessária da marca LuminaSmart.
                </p>
              </div>

              <div className="p-4 bg-brand-50 rounded-xl border border-brand-100">
                <h3 className="font-semibold text-brand-800 mb-2 flex items-center gap-2">
                  <LayoutTemplate size={18} />
                  Como funciona?
                </h3>
                <ul className="text-sm text-brand-700 space-y-2 list-disc list-inside">
                  <li>Conte os circuitos de iluminação</li>
                  <li>Conte os motores de cortina</li>
                  <li>Indique as zonas de climatização</li>
                  <li>Receba o BOM completo com módulos DIN, processadores e acessórios</li>
                </ul>
              </div>
            </div>

            {/* Right Col: Form */}
            <form onSubmit={handleSubmit} className="lg:col-span-2 space-y-8">

              {/* Project Info Section */}
              <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Nome do Projeto</label>
                    <input
                      required
                      type="text"
                      name="projectName"
                      placeholder="Ex: Residência Silva"
                      value={inputs.projectName}
                      onChange={handleTextChange}
                      className="w-full px-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none transition-all"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Integrador Responsável</label>
                    <input
                      required
                      type="text"
                      name="integratorName"
                      placeholder="Ex: Tech Solutions Ltda"
                      value={inputs.integratorName}
                      onChange={handleTextChange}
                      className="w-full px-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none transition-all"
                    />
                  </div>
                </div>
              </div>

              {/* Lighting Section */}
              <div className="space-y-3">
                <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                  <Lightbulb size={16} /> Iluminação
                </h3>
                <div className="grid gap-3">
                  <CounterInput 
                    label={DEVICE_LABELS[DeviceType.LIGHT_DIM]} 
                    value={inputs.counts[DeviceType.LIGHT_DIM]} 
                    onChange={(v) => handleCountChange(DeviceType.LIGHT_DIM, v)}
                  />
                  <CounterInput 
                    label={DEVICE_LABELS[DeviceType.LIGHT_ONOFF]} 
                    value={inputs.counts[DeviceType.LIGHT_ONOFF]} 
                    onChange={(v) => handleCountChange(DeviceType.LIGHT_ONOFF, v)}
                  />
                  <CounterInput 
                    label={DEVICE_LABELS[DeviceType.LIGHT_RGB]} 
                    value={inputs.counts[DeviceType.LIGHT_RGB]} 
                    onChange={(v) => handleCountChange(DeviceType.LIGHT_RGB, v)}
                  />
                </div>
              </div>

              {/* Shading Section */}
              <div className="space-y-3">
                <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                  <Blinds size={16} /> Cortinas e Persianas
                </h3>
                <div className="grid gap-3">
                  <CounterInput 
                    label={DEVICE_LABELS[DeviceType.CURTAIN_ROLLER]} 
                    value={inputs.counts[DeviceType.CURTAIN_ROLLER]} 
                    onChange={(v) => handleCountChange(DeviceType.CURTAIN_ROLLER, v)}
                  />
                  <CounterInput 
                    label={DEVICE_LABELS[DeviceType.CURTAIN_DRAPERY]} 
                    value={inputs.counts[DeviceType.CURTAIN_DRAPERY]} 
                    onChange={(v) => handleCountChange(DeviceType.CURTAIN_DRAPERY, v)}
                  />
                </div>
              </div>

              {/* Climate Section */}
              <div className="space-y-3">
                <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                  <Thermometer size={16} /> Climatização
                </h3>
                <div className="grid gap-3">
                  <CounterInput 
                    label={DEVICE_LABELS[DeviceType.AC_SPLIT]} 
                    value={inputs.counts[DeviceType.AC_SPLIT]} 
                    onChange={(v) => handleCountChange(DeviceType.AC_SPLIT, v)}
                  />
                  <CounterInput 
                    label={DEVICE_LABELS[DeviceType.AC_CENTRAL]} 
                    value={inputs.counts[DeviceType.AC_CENTRAL]} 
                    onChange={(v) => handleCountChange(DeviceType.AC_CENTRAL, v)}
                  />
                </div>
              </div>

              {/* Error Message */}
              {error && (
                <div className="p-4 bg-red-50 text-red-700 rounded-lg border border-red-200">
                  {error}
                </div>
              )}

              {/* Action Bar */}
              <div className="pt-4 border-t border-slate-200 sticky bottom-4">
                <button
                  type="submit"
                  disabled={loading || totalDevices === 0 || !inputs.projectName}
                  className="w-full bg-brand-600 hover:bg-brand-700 text-white font-bold py-4 rounded-xl shadow-lg hover:shadow-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3"
                >
                  {loading ? (
                    <>
                      <Loader2 className="animate-spin" /> Processando Regras de Inferência...
                    </>
                  ) : (
                    <>
                      Gerar Especificação <ArrowRight size={20} />
                    </>
                  )}
                </button>
                {totalDevices === 0 && (
                  <p className="text-center text-xs text-slate-400 mt-2">Adicione pelo menos um dispositivo para continuar.</p>
                )}
              </div>

            </form>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export enum DeviceType {
  LIGHT_DIM = 'LIGHT_DIM',
  LIGHT_ONOFF = 'LIGHT_ONOFF',
  LIGHT_RGB = 'LIGHT_RGB',
  CURTAIN_ROLLER = 'CURTAIN_ROLLER',
  CURTAIN_DRAPERY = 'CURTAIN_DRAPERY',
  AC_SPLIT = 'AC_SPLIT',
  AC_CENTRAL = 'AC_CENTRAL',
}

export type ProductCategory = 'Iluminação' | 'Cortinas' | 'Climatização' | 'Processador' | 'Acessório';

export interface Product {
  id: string;
  category: ProductCategory;
  type: string;
  brand: string;
  model: string;
  channels: number; // Capacity
  description?: string; // Optional description for AI context
}

export interface ProjectInputs {
  projectName: string;
  integratorName: string;
  counts: Record<DeviceType, number>;
}

export interface BomItem {
  sku: string;
  name: string;
  description: string;
  quantity: number;
  category: 'Controller' | 'Lighting' | 'Shading' | 'Climate' | 'Accessory';
  reasoning?: string;
}

export interface SpecificationResult {
  items: BomItem[];
  totalDevices: number;
  summary: string;
}

export const DEVICE_LABELS: Record<DeviceType, string> = {
  [DeviceType.LIGHT_DIM]: 'Circuitos Dimerizáveis',
  [DeviceType.LIGHT_ONOFF]: 'Circuitos On/Off (Relé)',
  [DeviceType.LIGHT_RGB]: 'Fitas LED RGB/RGBW',
  [DeviceType.CURTAIN_ROLLER]: 'Persianas Rolo (Motor Tubular)',
  [DeviceType.CURTAIN_DRAPERY]: 'Cortinas de Trilho (Abertura Central/Lateral)',
  [DeviceType.AC_SPLIT]: 'Ar Condicionado Split (IR)',
  [DeviceType.AC_CENTRAL]: 'Ar Condicionado Central (Termostato)',
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ProjectInputs, SpecificationResult, Product } from "../types";

const RESPONSE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    items: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          sku: { type: Type.STRING },
          name: { type: Type.STRING },
          description: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Controller', 'Lighting', 'Shading', 'Climate', 'Accessory'] },
          quantity: { type: Type.INTEGER },
          reasoning: { type: Type.STRING },
        },
        required: ['sku', 'name', 'category', 'quantity', 'reasoning'],
      },
    },
    totalDevices: { type: Type.INTEGER, description: "Total count of physical devices controlled" },
    summary: { type: Type.STRING, description: "A professional executive summary of the system designed." },
  },
  required: ['items', 'totalDevices', 'summary'],
};

// Helper to convert the Product array into a string prompt for the AI
const generateCatalogPrompt = (catalog: Product[]): string => {
  let catalogText = "## Available Product Catalog\n\n";

  // Group by category for cleaner prompting
  const categories = Array.from(new Set(catalog.map(p => p.category)));

  categories.forEach(cat => {
    catalogText += `### ${cat}\n`;
    const items = catalog.filter(p => p.category === cat);
    items.forEach(item => {
      catalogText += `- ID: ${item.id}\n`;
      catalogText += `  - Brand: ${item.brand}\n`;
      catalogText += `  - Model: ${item.model}\n`;
      catalogText += `  - Type: ${item.type}\n`;
      catalogText += `  - Capacity/Channels: ${item.channels}\n`;
      if (item.description) catalogText += `  - Notes: ${item.description}\n`;
    });
    catalogText += "\n";
  });

  return catalogText;
};

export const generateSpecification = async (inputs: ProjectInputs, catalog: Product[]): Promise<SpecificationResult> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please set process.env.API_KEY.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Filter out zero counts
  const activeInputs = Object.entries(inputs.counts)
    .filter(([_, count]) => count > 0)
    .map(([key, count]) => `${key}: ${count}`)
    .join('\n');

  if (!activeInputs) {
    throw new Error("No devices selected.");
  }

  const dynamicCatalogPrompt = generateCatalogPrompt(catalog);

  const SYSTEM_INSTRUCTION = `
    You are an expert Automation Specification Engineer.
    Your goal is to analyze project requirements and generate a Bill of Materials (BOM) using ONLY the products provided in the catalog below.

    ${dynamicCatalogPrompt}

    ## Logic Rules
    1. **Processor**: Always include at least one main processor if available in catalog (usually category 'Processador').
    2. **Calculation**: Calculate the minimum number of modules needed based on the 'Capacity/Channels' of the catalog items.
       - Example: If a Dimmer module has 4 channels, and user needs 6 dimmer circuits, you need 2 modules.
    3. **Matching**: 
       - LIGHT_DIM -> Match with Type 'Dimmer'
       - LIGHT_ONOFF -> Match with Type 'Relé'
       - CURTAIN_ROLLER/DRAPERY -> Match with Shading modules
       - AC -> Match with IR or Thermostats
    4. **Output**: Always provide a 'reasoning' for the quantity calculated.
  `;

  const prompt = `
    Project Name: ${inputs.projectName}
    Integrator: ${inputs.integratorName}

    Requested Devices:
    ${activeInputs}

    Please generate the specification based on the catalog provided.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: 'application/json',
        responseSchema: RESPONSE_SCHEMA,
        temperature: 0.1, 
      },
    });

    if (response.text) {
      return JSON.parse(response.text) as SpecificationResult;
    }
    throw new Error("No response generated.");
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

