// Helper to convert the Product array into a string prompt for the AI
const generateCatalogPrompt = (catalog: Product[]): string => {
  let catalogText = "## Available Product Catalog\n\n";

  // Group by category for cleaner prompting
  const categories = Array.from(new Set(catalog.map(p => p.category)));

  categories.forEach(cat => {
    catalogText += `### ${cat}\n`;
    const items = catalog.filter(p => p.category === cat);
    items.forEach(item => {
      catalogText += `- ID: ${item.id}\n`;
      catalogText += `  - Brand: ${item.brand}\n`;
      catalogText += `  - Model: ${item.model}\n`;
      catalogText += `  - Type: ${item.type}\n`;
      catalogText += `  - Capacity/Channels: ${item.channels}\n`;
      catalogText += `  - Power Specs: Consumes ${item.consumesPower}W, Supplies ${item.suppliesPower}W\n`;
      catalogText += `  - Address Specs: Consumes ${item.consumesAddress}, Supplies ${item.suppliesAddress}\n`;
      if (item.description) catalogText += `  - Notes: ${item.description}\n`;
    });
    catalogText += "\n";
  });

  return catalogText;
};

