interface BackofficeViewProps {
  catalog: Product[];
  onAddProduct: () => void;
  onRemoveProduct: (id: number) => void;
  onUpdateProduct: (product: Product) => void;
}

const CATEGORIES: ProductCategory[] = ['Processor', 'Lighting Control', 'Shades Control', 'HVAC Control'];

const getTypesForCategory = (cat: ProductCategory): string[] => {
  switch (cat) {
    case 'Processor': return ['Processor'];
    case 'Lighting Control': return ['Relay', 'Dimmer'];
    case 'Shades Control': return ['Wired', 'Wireless'];
    case 'HVAC Control': return ['IR', 'VRV/VRF'];
    default: return [];
  }
};

export const BackofficeView: React.FC<BackofficeViewProps> = ({ catalog, onAddProduct, onRemoveProduct, onUpdateProduct }) => {
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<Product | null>(null);

  const handleEditClick = (product: Product) => {
    setEditingId(product.id);
    setEditForm({ ...product });
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setEditForm(null);
  };

  const handleSaveEdit = () => {
    if (editForm) {
      onUpdateProduct(editForm);
      setEditingId(null);
      setEditForm(null);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (!editForm) return;
    const { name, value } = e.target;

    // Numeric handling
    const isFloat = name.includes('Power');
    const isInt = name === 'id' || name === 'channels' || name.includes('Address');

    let parsedValue: any = value;
    if (isFloat) parsedValue = parseFloat(value) || 0;
    if (isInt) parsedValue = parseInt(value) || 0;

    // Special logic: If category changes, reset type to first available
    if (name === 'category') {
        const newCategory = value as ProductCategory;
        const availableTypes = getTypesForCategory(newCategory);
        setEditForm({
            ...editForm,
            category: newCategory,
            type: availableTypes[0] || ''
        });
    } else {
        setEditForm(prev => prev ? ({ ...prev, [name]: parsedValue }) : null);
    }
  };

  return (
    <div className="space-y-8 animate-fade-in">
