          <button
            onClick={onAddProduct}
            className="bg-brand-600 hover:bg-brand-700 text-white font-bold py-2 px-4 rounded-lg shadow-sm text-sm flex items-center gap-2 transition-colors"
          >
            <Plus size={16} /> Nova Linha
          </button>
        </div>

        {/* Table */}
        <div className="overflow-x-auto border border-slate-200 rounded-lg">
          <table className="w-full text-left text-sm border-collapse">
            <thead className="bg-slate-100 text-slate-600 uppercase font-bold text-xs">
              <tr>
                <th rowSpan={2} className="px-3 py-2 border border-slate-200 bg-slate-50 w-16">ID</th>
                <th rowSpan={2} className="px-3 py-2 border border-slate-200 bg-slate-50">Brand</th>
                <th rowSpan={2} className="px-3 py-2 border border-slate-200 bg-slate-50">Model</th>
