                      <CounterInput 
                        label={DEVICE_LABELS[DeviceType.LIGHT_ONOFF]} 
                        value={inputs.counts[DeviceType.LIGHT_ONOFF]} 
                        onChange={(v) => handleCountChange(DeviceType.LIGHT_ONOFF, v)}
                      />
                      <CounterInput 
                        label={DEVICE_LABELS[DeviceType.LIGHT_RGB]} 
                        value={inputs.counts[DeviceType.LIGHT_RGB]} 
                        onChange={(v) => handleCountChange(DeviceType.LIGHT_RGB, v)}
                      />
                    </div>
                  </div>

                  {/* Shading Section */}
                  <div className="space-y-3">
                    <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                      <Blinds size={16} /> Cortinas e Persianas
                    </h3>
                    <div className="grid gap-3">
                      <CounterInput 
                        label={DEVICE_LABELS[DeviceType.CURTAIN_ROLLER]} 
                        value={inputs.counts[DeviceType.CURTAIN_ROLLER]} 
