                      <CounterInput 
                        label={DEVICE_LABELS[DeviceType.CURTAIN_DRAPERY]} 
                        value={inputs.counts[DeviceType.CURTAIN_DRAPERY]} 
                        onChange={(v) => handleCountChange(DeviceType.CURTAIN_DRAPERY, v)}
