import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ProjectInputs, SpecificationResult, Product } from "../types";

const RESPONSE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    items: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          sku: { type: Type.STRING },
          name: { type: Type.STRING },
          description: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Controller', 'Lighting', 'Shading', 'Climate', 'Accessory'] },
          quantity: { type: Type.INTEGER },
          reasoning: { type: Type.STRING },
        },
        required: ['sku', 'name', 'category', 'quantity', 'reasoning'],
      },
    },
    totalDevices: { type: Type.INTEGER, description: "Total count of physical devices controlled" },
    summary: { type: Type.STRING, description: "A professional executive summary of the system designed." },
  },
  required: ['items', 'totalDevices', 'summary'],
};

// Helper to convert the Product array into a string prompt for the AI
const generateCatalogPrompt = (catalog: Product[]): string => {
  let catalogText = "## Available Product Catalog\n\n";

  // Group by category for cleaner prompting
  const categories = Array.from(new Set(catalog.map(p => p.category)));

  categories.forEach(cat => {
    catalogText += `### ${cat}\n`;
    const items = catalog.filter(p => p.category === cat);
    items.forEach(item => {
      catalogText += `- ID: ${item.id}\n`;
      catalogText += `  - Brand: ${item.brand}\n`;
      catalogText += `  - Model: ${item.model}\n`;
      catalogText += `  - Type: ${item.type}\n`;
      catalogText += `  - Capacity/Channels: ${item.channels}\n`;
      catalogText += `  - Power Specs: Consumes ${item.consumesPower}W, Supplies ${item.suppliesPower}W\n`;
      catalogText += `  - Address Specs: Consumes ${item.consumesAddress}, Supplies ${item.suppliesAddress}\n`;
      if (item.description) catalogText += `  - Notes: ${item.description}\n`;
    });
    catalogText += "\n";
  });

  return catalogText;
};

export const generateSpecification = async (inputs: ProjectInputs, catalog: Product[]): Promise<SpecificationResult> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please set process.env.API_KEY.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Filter out zero counts
  const activeInputs = Object.entries(inputs.counts)
    .filter(([_, count]) => count > 0)
    .map(([key, count]) => `${key}: ${count}`)
    .join('\n');

  if (!activeInputs) {
    throw new Error("No devices selected.");
  }

  const dynamicCatalogPrompt = generateCatalogPrompt(catalog);

  const SYSTEM_INSTRUCTION = `
    You are an expert Automation Specification Engineer.
    Your goal is to analyze project requirements and generate a Bill of Materials (BOM) using ONLY the products provided in the catalog below.

    ${dynamicCatalogPrompt}

    ## Inference Rules & Logic

    1. **Mandatory Processor**: 
       - Every system MUST include at least one main processor (Category: 'Processor').
       - If multiple processors are available, choose the most appropriate one.
       - The processor is the core of the system and is required even for small projects.

    2. **Device Matching (Input -> Catalog Type)**:
       - LIGHT_DIM -> Lighting Control (Type: Dimmer)
       - LIGHT_ONOFF -> Lighting Control (Type: Relay)
       - LIGHT_RGB -> Lighting Control (Type: LED Driver/RGB)
       - CURTAIN_ROLLER / CURTAIN_DRAPERY -> Shades Control
       - AC_SPLIT / AC_CENTRAL -> HVAC Control

    3. **Quantity Calculation (Dimensioning)**:
       - For each device type, calculate the required number of modules.
       - Formula: CEIL(Input Count / Module Channels).
       - Example: User requests 10 dimmable circuits. Catalog has an 8-channel dimmer.
         Calculation: 10 / 8 = 1.25 -> Round up to 2 modules.
       - Always optimize for the fewest modules unless redundancy is requested.

    4. **Output Format**:
       - 'sku': Use the Model name as SKU.
       - 'category': Map to the closest schema category (Controller, Lighting, Shading, Climate, Accessory).
       - 'reasoning': You MUST explicitly state the math. E.g., "10 circuits / 8 channels = 1.25 -> 2 modules".
  `;

  const prompt = `
    Project Name: ${inputs.projectName}
    Integrator: ${inputs.integratorName}

    Requested Devices (Input Counts):
    ${activeInputs}

    Please generate the specification based on the catalog provided.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: 'application/json',
        responseSchema: RESPONSE_SCHEMA,
        temperature: 0.1, 
      },
    });

    if (response.text) {
      return JSON.parse(response.text) as SpecificationResult;
    }
    throw new Error("No response generated.");
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import { ProjectInputs, SpecificationResult, Product, DeviceType, BomItem } from "../types";

export const generateSpecification = async (inputs: ProjectInputs, catalog: Product[]): Promise<SpecificationResult> => {
  const items: BomItem[] = [];
  const activeCounts = inputs.counts;

  // --- Rule 1: Mandatory Processor ---
  // Every system requires at least one processor.
  const processors = catalog.filter(p => p.category === 'Processor');

  if (processors.length > 0) {
    // Strategy: Pick the first available processor. 
    // In a real scenario, you might check address capacity limits here.
    const processor = processors[0];
    items.push({
        sku: processor.model,
        name: `${processor.brand} ${processor.type}`,
        description: processor.description || 'System Processor',
        quantity: 1,
        category: 'Controller',
        reasoning: 'Mandatory: 1 Main Processor required per system.'
    });
  }

  // --- Helper: Generic Device to Module Mapping Rule ---
  const processRule = (
      deviceTypes: DeviceType[],
      targetCategory: string,
      targetTypeKeywords: string[], // Array of keywords to match type (OR logic)
      bomCategory: BomItem['category']
  ) => {
      // 1. Calculate total load for this rule
      let totalNeeded = 0;
      deviceTypes.forEach(dt => totalNeeded += (activeCounts[dt] || 0));

      if (totalNeeded === 0) return;

      // 2. Find matching products in catalog
      const candidates = catalog.filter(p => {
          if (p.category !== targetCategory) return false;
          // Check if product type contains any of the keywords (case insensitive)
          return targetTypeKeywords.some(keyword => 
              p.type.toLowerCase().includes(keyword.toLowerCase())
          );
      });

      // 3. Select Best Fit (Greedy: Largest Channel Capacity)
      // Sort descending by channels
      candidates.sort((a, b) => b.channels - a.channels);

      if (candidates.length > 0) {
          const product = candidates[0];
          const capacity = product.channels || 1; // Prevent division by zero

          // 4. Calculate Quantity
          const quantity = Math.ceil(totalNeeded / capacity);

          items.push({
              sku: product.model,
              name: `${product.brand} ${product.type}`,
              description: product.description || `${product.category} Module (${capacity} Ch)`,
              quantity,
              category: bomCategory,
              reasoning: `${totalNeeded} devices / ${capacity} ch capacity = ${quantity} units required.`
          });
      } else {
          // Optional: Add a warning item if no product found?
          // For now, we just skip.
          console.warn(`No product found for ${targetCategory} [${targetTypeKeywords.join(',')}]`);
      }
  };

  // --- Rule 2: Lighting Control ---
  // Dimmers
  processRule([DeviceType.LIGHT_DIM], 'Lighting Control', ['Dimmer'], 'Lighting');
  // Relays
  processRule([DeviceType.LIGHT_ONOFF], 'Lighting Control', ['Relay'], 'Lighting');
  // RGB (LED Drivers)
  processRule([DeviceType.LIGHT_RGB], 'Lighting Control', ['RGB', 'LED'], 'Lighting');

  // --- Rule 3: Shading Control ---
  // Combine Roller and Drapery into standard Shade Controllers (assuming Wired)
  processRule(
      [DeviceType.CURTAIN_ROLLER, DeviceType.CURTAIN_DRAPERY], 
      'Shades Control', 
      ['Wired', 'Relay'], 
      'Shading'
  );

  // --- Rule 4: HVAC Control ---
  // Split typically uses IR Emitters
  processRule([DeviceType.AC_SPLIT], 'HVAC Control', ['IR', 'Infrared'], 'Climate');
  // Central typically uses VRV/VRF Gateways
  processRule([DeviceType.AC_CENTRAL], 'HVAC Control', ['VRV', 'VRF'], 'Climate');

  // --- Rule 5: Keypads (Placeholder Logic) ---
  // If we wanted to add logic for keypads based on room count, we could.
  // For now, only explicit device control is implemented.

  const totalDevices = Object.values(activeCounts).reduce((a, b) => a + b, 0);

  return {
    items,
    totalDevices,
    summary: `Technical specification generated based on deterministic capacity rules. The BOM includes controllers for ${totalDevices} endpoints along with the required central processing unit.`
  };
};

import React, { useState } from 'react';
import { Product, ProductCategory } from '../types';
import { Plus, Trash2, Database, Save, X, Pencil, RotateCcw } from 'lucide-react';

interface BackofficeViewProps {
  catalog: Product[];
  onAddProduct: () => void;
  onRemoveProduct: (id: number) => void;
  onUpdateProduct: (product: Product) => void;
}

const CATEGORIES: ProductCategory[] = ['Processor', 'Lighting Control', 'Shades Control', 'HVAC Control', 'Power Supply', 'Keypad', 'Sensor'];

const getTypesForCategory = (cat: ProductCategory): string[] => {
  switch (cat) {
    case 'Processor': return ['Processor'];
    case 'Lighting Control': return ['Relay', 'Dimmer', 'RGB'];
    case 'Shades Control': return ['Wired', 'Wireless'];
    case 'HVAC Control': return ['IR', 'VRV/VRF'];
    case 'Power Supply': return ['Bus Power', 'Auxiliary'];
    case 'Keypad': return ['Standard', 'Touch', 'Thermostat'];
    case 'Sensor': return ['Motion', 'Presence', 'Lux', 'Temp'];
    default: return ['Standard'];
  }
};

const INPUT_CLASS = "w-full bg-white border border-slate-200 rounded px-2 py-1.5 text-xs text-slate-700 focus:border-brand-500 focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-sm";
const SELECT_CLASS = "w-full bg-white border border-slate-200 rounded px-1 py-1.5 text-xs text-slate-700 focus:border-brand-500 focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-sm";

