import { ProjectInputs, SpecificationResult, Product, DeviceType, BomItem } from "../types";

export const generateSpecification = async (inputs: ProjectInputs, catalog: Product[]): Promise<SpecificationResult> => {
  const items: BomItem[] = [];
  const activeCounts = inputs.counts;

  // --- Rule 1: Mandatory Processor ---
  // Every system requires at least one processor.
  const processors = catalog.filter(p => p.category === 'Processor');

  if (processors.length > 0) {
    // Strategy: Pick the first available processor. 
    const processor = processors[0];
    items.push({
        sku: processor.model,
        name: `${processor.brand} ${processor.type}`,
        description: processor.description || 'System Processor',
        quantity: 1,
        category: 'Controller',
        reasoning: 'Mandatory: 1 Main Processor required per system.'
    });
  }

  // --- Configuration: Device Groups & Matching Rules ---
  // This structure defines which User Inputs map to which Catalog Categories/Types
  const INF_GROUPS = [
    {
      id: 'DIMMER_GROUP',
      // Inputs to aggregate
      types: [DeviceType.LIGHT_DIM],
      // Catalog filters
      targetCategory: 'Lighting Control',
      typeKeywords: ['Dimmer'],
      // Output category
      bomCategory: 'Lighting' as const
    },
    {
      id: 'RELAY_GROUP',
      types: [DeviceType.LIGHT_ONOFF],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Relay'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'RGB_GROUP',
      types: [DeviceType.LIGHT_RGB],
      targetCategory: 'Lighting Control',
      typeKeywords: ['RGB', 'LED'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'SHADE_GROUP',
      // Combine Rollers and Draperies as they usually both use standard motor controllers
      types: [DeviceType.CURTAIN_ROLLER, DeviceType.CURTAIN_DRAPERY],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wired', 'Relay', 'Motor'],
      bomCategory: 'Shading' as const
    },
    {
      id: 'HVAC_SPLIT_GROUP',
      types: [DeviceType.AC_SPLIT],
      targetCategory: 'HVAC Control',
      typeKeywords: ['IR', 'Infrared', 'Emitter'],
      bomCategory: 'Climate' as const
    },
    {
      id: 'HVAC_CENTRAL_GROUP',
      types: [DeviceType.AC_CENTRAL],
      targetCategory: 'HVAC Control',
      typeKeywords: ['VRV', 'VRF', 'Gateway', 'Thermostat'],
      bomCategory: 'Climate' as const
    }
  ];

  // --- Execution: Run the table ---
  INF_GROUPS.forEach(group => {
    // 1. Sum up the total load for this group
    const totalLoad = group.types.reduce((sum, type) => sum + (activeCounts[type] || 0), 0);

    if (totalLoad <= 0) return; // Skip if no devices of this type

    // 2. Find compatible products in the catalog
    const candidates = catalog.filter(product => {
      // Must match Category
      if (product.category !== group.targetCategory) return false;

      // Must match at least one keyword in Type (case-insensitive)
      const productType = product.type.toLowerCase();
      const hasKeyword = group.typeKeywords.some(keyword => productType.includes(keyword.toLowerCase()));

      return hasKeyword;
    });

    if (candidates.length === 0) {
      // No product found to control this load
      // Ideally we would add a warning item to the BOM
      items.push({
        sku: 'MISSING-PRODUCT',
        name: `Missing Product for ${group.id}`,
        description: `No catalog item found to control ${totalLoad} devices of type ${group.typeKeywords.join('/')}`,
        quantity: 0,
        category: 'Accessory',
        reasoning: `Catalog missing valid ${group.targetCategory} items.`
      });
      return;
    }

    // 3. Optimization Strategy: "Use as less as possible"
    // To minimize the module count, we prioritize the product with the HIGHEST channel capacity.
    candidates.sort((a, b) => b.channels - a.channels);

    const bestProduct = candidates[0];
    const capacity = bestProduct.channels > 0 ? bestProduct.channels : 1; // Safety for 0-channel items (like single units)

    // 4. Calculate Quantity
    // e.g., 10 circuits / 8 channels = 1.25 -> 2 modules
    const quantity = Math.ceil(totalLoad / capacity);

    // 5. Add to BOM
    items.push({
      sku: bestProduct.model,
      name: `${bestProduct.brand} ${bestProduct.type}`,
      description: bestProduct.description || `${bestProduct.category} Module (${capacity} Ch)`,
      quantity: quantity,
      category: group.bomCategory,
      reasoning: `Total Load: ${totalLoad}. Selected ${bestProduct.model} (Cap: ${capacity}). Math: ${totalLoad}/${capacity} = ${quantity} units.`
    });
  });

  const totalDevices = Object.values(activeCounts).reduce((a, b) => a + b, 0);

  return {
    items,
    totalDevices,
    summary: `Technical specification generated based on deterministic capacity rules. The BOM includes controllers for ${totalDevices} endpoints along with the required central processing unit.`
  };
};

