    },
    {
      id: 'SHADE_GROUP',
      types: [DeviceType.CURTAIN_ROLLER, DeviceType.CURTAIN_DRAPERY],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wired', 'Relay', 'Motor', 'LX'],
      bomCategory: 'Shading' as const
    },
    {
      id: 'HVAC_SPLIT_GROUP',
      types: [DeviceType.AC_SPLIT],
      targetCategory: 'HVAC Control',
      typeKeywords: ['IR', 'Infrared', 'Emitter', 'SA1'],
      bomCategory: 'Climate' as const
    },
    {
      id: 'HVAC_CENTRAL_GROUP',
      types: [DeviceType.AC_CENTRAL],
      targetCategory: 'HVAC Control',
      typeKeywords: ['VRV', 'VRF', 'Gateway', 'Thermostat', 'DK'],
      bomCategory: 'Climate' as const
    }
  ];

  // --- Optimized Hardware Algorithm Implementation ---
  const addOptimizedItems = (total: number, candidates: Product[], group: typeof INF_GROUPS[0]) => {
    // 1. Identify specific channel variants
    const mod12 = candidates.find(p => p.channels === 12);
    const mod8 = candidates.find(p => p.channels === 8);
    const mod4 = candidates.find(p => p.channels === 4);

    // 2. Logic Check: If we have the 12/8/4 triad (or at least one of them), use the optimized algorithm
    // Otherwise, fall back to the greedy highest-capacity approach
    if (mod12 || mod8 || mod4) {
      let q12 = 0;
      let q8 = 0;
      let q4 = 0;

      // The algorithm: Use 12s for everything possible
      q12 = Math.floor(total / 12);
      const remainder = total % 12;

      if (remainder > 0) {
        if (remainder <= 4 && mod4) {
          q4 = 1;
        } else if (remainder <= 8 && mod8) {
          q8 = 1;
        } else if (mod12) {
          // If remainder > 8 or we don't have 8/4, add another 12
          q12 += 1;
        } else if (mod8) {
           // We have 8 but not 12
           q8 += 1;
        } else if (mod4) {
           // We only have 4
           q4 += Math.ceil(remainder / 4);
        }
      }

      // Add found items to BOM
      if (q12 > 0 && mod12) items.push({
        sku: mod12.model,
        name: `${mod12.brand} ${mod12.type}`,
        description: `${mod12.category} (12 Ch)`,
        quantity: q12,
        category: group.bomCategory,
        reasoning: `Optimizado: Uso de módulos de 12 canais para carga principal (${total} pontos).`
      });
      if (q8 > 0 && mod8) items.push({
        sku: mod8.model,
        name: `${mod8.brand} ${mod8.type}`,
        description: `${mod8.category} (8 Ch)`,
        quantity: q8,
        category: group.bomCategory,
        reasoning: `Optimizado: Módulo de 8 canais selecionado para o restante de ${total % 12}.`
      });
      if (q4 > 0 && mod4) items.push({
        sku: mod4.model,
        name: `${mod4.brand} ${mod4.type}`,
        description: `${mod4.category} (4 Ch)`,
        quantity: q4,
        category: group.bomCategory,
        reasoning: `Optimizado: Módulo de 4 canais selecionado para o restante de ${total % 12}.`
      });
    } else {
      // Fallback: Use the highest capacity available product (Standard greedy)
      candidates.sort((a, b) => b.channels - a.channels);
      const best = candidates[0];
      const cap = best.channels || 1;
      const qty = Math.ceil(total / cap);

      items.push({
        sku: best.model,
        name: `${best.brand} ${best.type}`,
        description: `${best.category} (${cap} Ch)`,
        quantity: qty,
        category: group.bomCategory,
        reasoning: `Padrão: ${total} unidades / capacidade de ${cap} canais = ${qty} módulos.`
      });
    }
  };

  // --- Execution Loop ---
  INF_GROUPS.forEach(group => {
    const totalLoad = group.types.reduce((sum, type) => sum + (activeCounts[type] || 0), 0);
    if (totalLoad <= 0) return;

    const candidates = catalog.filter(p => 
      p.category === group.targetCategory && 
      group.typeKeywords.some(k => 
        p.type.toLowerCase().includes(k.toLowerCase()) || 
        p.model.toLowerCase().includes(k.toLowerCase())
      )
    );

    if (candidates.length === 0) {
      items.push({
        sku: 'MISSING-PRODUCT',
        name: `Incompatível: ${group.id}`,
        description: `Nenhum produto no catálogo para controlar ${totalLoad} dispositivos.`,
        quantity: 0,
        category: 'Accessory',
        reasoning: `Erro: Falta cadastrar módulos de ${group.targetCategory} no Backoffice.`
      });
      return;
    }

    addOptimizedItems(totalLoad, candidates, group);
  });

  const totalDevices = Object.values(activeCounts).reduce((a, b) => a + b, 0);

  return {
    items,
    totalDevices,
    summary: `Especificação técnica otimizada para minimizar a quantidade de módulos físicos. Foram considerados processamento central e controle para ${totalDevices} pontos de automação.`
