    // Generate a temporary ID (max ID + 1)
    const newId = catalog.length > 0 ? Math.max(...catalog.map(p => p.id)) + 1 : 1000;
    const newProduct: Product = {
        id: newId,
        brand: 'ROEHN',
        model: 'Novo Modelo',
