import { ProjectInputs, SpecificationResult, Product, DeviceType, BomItem } from "../types";

export const generateSpecification = async (inputs: ProjectInputs, catalog: Product[]): Promise<SpecificationResult> => {
  const items: BomItem[] = [];
  const activeCounts = inputs.counts;

  // --- Rule 1: Mandatory Processor ---
  const processors = catalog.filter(p => p.category === 'Processor');
  if (processors.length > 0) {
    const processor = processors[0];
    items.push({
        sku: processor.model,
        name: `${processor.brand} ${processor.type}`,
        description: processor.description || 'Processador Central do Sistema',
        quantity: 1,
        category: 'Controller',
        reasoning: 'Obrigatório: 1 Processador principal por sistema.'
    });
  }

  // --- Configuration: Device Groups & Matching Rules ---
  const INF_GROUPS = [
    {
      id: 'DIMMER_GROUP',
      types: [DeviceType.LIGHT_DIM],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Dimmer'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'RELAY_GROUP',
      types: [DeviceType.LIGHT_ONOFF],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Relay', 'RL'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'RGB_GROUP',
      types: [DeviceType.LIGHT_RGB],
      targetCategory: 'Lighting Control',
      typeKeywords: ['RGB', 'LED', 'PWM'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'SHADE_GROUP',
      types: [DeviceType.CURTAIN_ROLLER, DeviceType.CURTAIN_DRAPERY],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wired', 'Relay', 'Motor', 'LX'],
      bomCategory: 'Shading' as const
    },
    {
      id: 'HVAC_SPLIT_GROUP',
      types: [DeviceType.AC_SPLIT],
      targetCategory: 'HVAC Control',
      typeKeywords: ['IR', 'Infrared', 'Emitter', 'SA1'],
      bomCategory: 'Climate' as const
    },
    {
      id: 'HVAC_CENTRAL_GROUP',
      types: [DeviceType.AC_CENTRAL],
      targetCategory: 'HVAC Control',
      typeKeywords: ['VRV', 'VRF', 'Gateway', 'Thermostat', 'DK'],
      bomCategory: 'Climate' as const
    }
  ];

  // --- Generic Optimized Hardware Algorithm ---
  const addOptimizedItemsGeneric = (total: number, candidates: Product[], group: typeof INF_GROUPS[0]) => {
    // 1. Get unique channel options sorted descending
    // We group by capacity and take the first product found for each capacity level
    const productsByCapacity = new Map<number, Product>();
    candidates.forEach(p => {
      if (!productsByCapacity.has(p.channels)) {
        productsByCapacity.set(p.channels, p);
      }
    });

    const capacities = Array.from(productsByCapacity.keys()).sort((a, b) => b - a);

    if (capacities.length === 0) return;

    const maxCap = capacities[0];
    const maxProduct = productsByCapacity.get(maxCap)!;

    // 2. Handle the bulk using the largest module
    let bulkQty = Math.floor(total / maxCap);
    const remainder = total % maxCap;

    // Track quantities for the BOM
    const bomSummary = new Map<string, { product: Product, qty: number }>();

    if (bulkQty > 0) {
      bomSummary.set(maxProduct.model, { product: maxProduct, qty: bulkQty });
    }

    // 3. Handle the remainder specifically to minimize module count (Generic Algorithm)
    if (remainder > 0) {
      // Find the module with the smallest capacity that is still >= remainder
      const bestFitCap = capacities
        .filter(cap => cap >= remainder)
        .sort((a, b) => a - b)[0]; // Sort ascending to get the smallest fit

      if (bestFitCap !== undefined) {
        const fitProduct = productsByCapacity.get(bestFitCap)!;
        const current = bomSummary.get(fitProduct.model) || { product: fitProduct, qty: 0 };
        bomSummary.set(fitProduct.model, { ...current, qty: current.qty + 1 });
      } else {
        // If the remainder is larger than our largest single module (shouldn't happen with % logic),
        // or no module fits the remainder as a single unit, just add another largest module
        const current = bomSummary.get(maxProduct.model) || { product: maxProduct, qty: 0 };
        bomSummary.set(maxProduct.model, { ...current, qty: current.qty + 1 });
      }
    }

    // 4. Convert Summary Map to BOM Items
    bomSummary.forEach(({ product, qty }, model) => {
      if (qty > 0) {
        items.push({
          sku: product.model,
          name: `${product.brand} ${product.type}`,
          description: `${product.category} (${product.channels} Canais)`,
          quantity: qty,
          category: group.bomCategory,
          reasoning: `Otimização Genérica: Total ${total} pontos. Módulos de ${product.channels} canais usados para eficiência de hardware.`
        });
      }
    });
  };

  // --- Execution Loop ---
  INF_GROUPS.forEach(group => {
    const totalLoad = group.types.reduce((sum, type) => sum + (activeCounts[type] || 0), 0);
    if (totalLoad <= 0) return;

    // Filter candidates by category and type keywords
    const candidates = catalog.filter(p => 
      p.category === group.targetCategory && 
      group.typeKeywords.some(k => 
        p.type.toLowerCase().includes(k.toLowerCase()) || 
        p.model.toLowerCase().includes(k.toLowerCase())
      )
    );

    if (candidates.length === 0) {
      items.push({
        sku: 'MISSING-PRODUCT',
        name: `Não Encontrado: ${group.id}`,
        description: `Nenhum produto no catálogo para controlar ${totalLoad} dispositivos.`,
        quantity: 0,
        category: 'Accessory',
        reasoning: `Erro: Verifique o cadastro de módulos de ${group.targetCategory} no Backoffice.`
      });
      return;
    }

    addOptimizedItemsGeneric(totalLoad, candidates, group);
  });

  const totalDevices = Object.values(activeCounts).reduce((a, b) => a + b, 0);

  return {
    items,
    totalDevices,
    summary: `Especificação técnica gerada via algoritmo de otimização genérica. Hardware selecionado automaticamente para controlar ${totalDevices} pontos com o menor número de módulos físicos possível.`
  };
};

