  onUpdateProduct: (product: Product) => void;
}

const CATEGORIES: ProductCategory[] = ['Processor', 'Lighting Control', 'Shades Control', 'HVAC Control', 'Power Supply', 'Keypad', 'Sensor'];

const getTypesForCategory = (cat: ProductCategory): string[] => {
  switch (cat) {
    case 'Processor': return ['Processor'];
    case 'Lighting Control': return ['Relay', 'Dimmer', 'PWM', 'DALI', 'RGB'];
    case 'Shades Control': return ['Wired', 'Wireless'];
    case 'HVAC Control': return ['IR', 'VRV/VRF'];
    case 'Power Supply': return ['Bus Power', 'Auxiliary'];
    case 'Keypad': return ['Standard', 'Touch', 'Thermostat'];
    case 'Sensor': return ['Motion', 'Presence', 'Lux', 'Temp'];
    default: return ['Standard'];
  }
};

