  SHADE_WIRELESS = 'SHADE_WIRELESS',
  // Climate
  CLIMATE_IR = 'CLIMATE_IR',
  CLIMATE_VRV = 'CLIMATE_VRV',
}

export type ProductCategory = 'Processor' | 'Lighting Control' | 'Shades Control' | 'HVAC Control' | 'Power Supply' | 'Keypad' | 'Sensor';

export interface Product {
  id: number;
  category: ProductCategory;
