                    </h3>
                    <div className="grid gap-3">
                      <CounterInput 
                        label={DEVICE_LABELS[DeviceType.CLIMATE_IR]} 
                        value={inputs.counts[DeviceType.CLIMATE_IR]} 
                        onChange={(v) => handleCountChange(DeviceType.CLIMATE_IR, v)}
                      />
                      <CounterInput 
                        label={DEVICE_LABELS[DeviceType.CLIMATE_VRV]} 
                        value={inputs.counts[DeviceType.CLIMATE_VRV]} 
                        onChange={(v) => handleCountChange(DeviceType.CLIMATE_VRV, v)}
                      />
                    </div>
                  </div>

                  {error && (
                    <div className="p-4 bg-red-50 text-red-700 rounded-lg border border-red-200">
                      {error}
                    </div>
                  )}

                  <div className="pt-4 border-t border-slate-200 sticky bottom-4">
                    <button
                      type="submit"
                      disabled={loading || totalDevices === 0 || !inputs.projectName}
                      className="w-full bg-brand-600 hover:bg-brand-700 text-white font-bold py-4 rounded-xl shadow-lg hover:shadow-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3"
                    >
                      {loading ? (
                        <>
                          <Loader2 className="animate-spin" /> Calculating...
                        </>
                      ) : (
                        <>
                          Generate Specification <ArrowRight size={20} />
                        </>
                      )}
                    </button>
                    {totalDevices === 0 && (
                      <p className="text-center text-xs text-slate-400 mt-2">Add at least one device to proceed.</p>
                    )}
                  </div>
                </form>
              </div>
            )}
          </>
        )}
      </main>
    </div>
  );
};

