import { ProjectInputs, SpecificationResult, Product, DeviceType, BomItem } from "../types";

export const generateSpecification = async (inputs: ProjectInputs, catalog: Product[]): Promise<SpecificationResult> => {
  const items: BomItem[] = [];
  const activeCounts = inputs.counts;

  // --- Rule 1: Mandatory Processor ---
  const processors = catalog.filter(p => p.category === 'Processor');
  if (processors.length > 0) {
    const processor = processors[0];
    items.push({
        sku: processor.model,
        name: `${processor.brand} ${processor.type}`,
        description: processor.description || 'System Central Processor',
        quantity: 1,
        category: 'Controller',
        reasoning: 'Mandatory: 1 Main Processor required per system.'
    });
  }

  // --- Configuration: Device Groups & Matching Rules ---
  const INF_GROUPS = [
    {
      id: 'DIMMER_GROUP',
      types: [DeviceType.LIGHT_DIMMER],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Dimmer'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'RELAY_GROUP',
      types: [DeviceType.LIGHT_ONOFF],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Relay', 'RL', 'On/Off'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'PWM_GROUP',
      types: [DeviceType.LIGHT_PWM],
      targetCategory: 'Lighting Control',
      typeKeywords: ['PWM', 'LED', 'RGB'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'DALI_GROUP',
      types: [DeviceType.LIGHT_DALI],
      targetCategory: 'Lighting Control',
      typeKeywords: ['DALI', 'DL'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'SHADE_WIRED_GROUP',
      types: [DeviceType.SHADE_WIRED],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wired', 'LX'],
      bomCategory: 'Shading' as const
    },
    {
      id: 'SHADE_WIRELESS_GROUP',
      types: [DeviceType.SHADE_WIRELESS],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wireless', 'GTW'],
      bomCategory: 'Shading' as const
    },
    {
      id: 'HVAC_IR_GROUP',
      types: [DeviceType.CLIMATE_IR],
      targetCategory: 'HVAC Control',
      typeKeywords: ['IR', 'Infrared', 'Emitter', 'SA1'],
      bomCategory: 'Climate' as const
    },
    {
      id: 'HVAC_CENTRAL_GROUP',
      types: [DeviceType.CLIMATE_VRV],
      targetCategory: 'HVAC Control',
      typeKeywords: ['VRV', 'VRF', 'Gateway', 'Thermostat', 'DK'],
      bomCategory: 'Climate' as const
    }
  ];

  // --- Generic Optimized Hardware Algorithm ---
  const addOptimizedItemsGeneric = (total: number, candidates: Product[], group: typeof INF_GROUPS[0]) => {
    const productsByCapacity = new Map<number, Product>();
    candidates.forEach(p => {
      if (!productsByCapacity.has(p.channels)) {
        productsByCapacity.set(p.channels, p);
      }
    });

    const capacities = Array.from(productsByCapacity.keys()).sort((a, b) => b - a);

    if (capacities.length === 0) return;

    const maxCap = capacities[0];
    const maxProduct = productsByCapacity.get(maxCap)!;

    let bulkQty = Math.floor(total / maxCap);
    const remainder = total % maxCap;

    const bomSummary = new Map<string, { product: Product, qty: number }>();

    if (bulkQty > 0) {
      bomSummary.set(maxProduct.model, { product: maxProduct, qty: bulkQty });
    }

    if (remainder > 0) {
      const bestFitCap = capacities
        .filter(cap => cap >= remainder)
        .sort((a, b) => a - b)[0];

      if (bestFitCap !== undefined) {
        const fitProduct = productsByCapacity.get(bestFitCap)!;
        const current = bomSummary.get(fitProduct.model) || { product: fitProduct, qty: 0 };
        bomSummary.set(fitProduct.model, { ...current, qty: current.qty + 1 });
      } else {
        const current = bomSummary.get(maxProduct.model) || { product: maxProduct, qty: 0 };
        bomSummary.set(maxProduct.model, { ...current, qty: current.qty + 1 });
      }
    }

    bomSummary.forEach(({ product, qty }, model) => {
      if (qty > 0) {
        items.push({
          sku: product.model,
          name: `${product.brand} ${product.type}`,
          description: `${product.category} (${product.channels} Channels)`,
          quantity: qty,
          category: group.bomCategory,
          reasoning: `Generic Optimization: Total ${total} loads. ${product.channels}-ch modules selected for hardware efficiency.`
        });
      }
    });
  };

  INF_GROUPS.forEach(group => {
    const totalLoad = group.types.reduce((sum, type) => sum + (activeCounts[type] || 0), 0);
    if (totalLoad <= 0) return;

    const candidates = catalog.filter(p => 
      p.category === group.targetCategory && 
      group.typeKeywords.some(k => 
        p.type.toLowerCase().includes(k.toLowerCase()) || 
        p.model.toLowerCase().includes(k.toLowerCase())
      )
    );

    if (candidates.length === 0) {
      items.push({
        sku: 'MISSING-PRODUCT',
        name: `Incompatible: ${group.id}`,
        description: `No catalog products found to control ${totalLoad} devices.`,
        quantity: 0,
        category: 'Accessory',
        reasoning: `Error: Missing ${group.targetCategory} products in Backoffice.`
      });
      return;
    }

    addOptimizedItemsGeneric(totalLoad, candidates, group);
  });

  const totalDevices = Object.values(activeCounts).reduce((a, b) => a + b, 0);

  return {
    items,
    totalDevices,
    summary: `Technical specification generated via generic optimization algorithm. Hardware automatically selected to control ${totalDevices} endpoints with the minimum number of physical modules.`
  };
};

import React, { useState } from 'react';
import { Product, ProductCategory } from '../types';
import { Plus, Trash2, Database, Save, X, Pencil } from 'lucide-react';

interface BackofficeViewProps {
  catalog: Product[];
  onAddProduct: () => void;
  onRemoveProduct: (id: number) => void;
  onUpdateProduct: (product: Product) => void;
}

const CATEGORIES: ProductCategory[] = ['Processor', 'Lighting Control', 'Shades Control', 'HVAC Control', 'Power Supply', 'Keypad', 'Sensor'];

const getTypesForCategory = (cat: ProductCategory): string[] => {
  switch (cat) {
    case 'Processor': return ['Processor'];
    case 'Lighting Control': return ['On/Off', 'Dimmer', 'PWM', 'DALI'];
    case 'Shades Control': return ['Wired', 'Wireless'];
    case 'HVAC Control': return ['Infrared', 'VRV/VRF'];
    case 'Power Supply': return ['Bus Power', 'Auxiliary'];
    case 'Keypad': return ['Standard', 'Touch', 'Thermostat'];
    case 'Sensor': return ['Motion', 'Presence', 'Lux', 'Temp'];
    default: return ['Standard'];
  }
};

const INPUT_CLASS = "w-full bg-white border border-slate-200 rounded px-2 py-1.5 text-xs text-slate-700 focus:border-brand-500 focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-sm";
const SELECT_CLASS = "w-full bg-white border border-slate-200 rounded px-1 py-1.5 text-xs text-slate-700 focus:border-brand-500 focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-sm";

export const BackofficeView: React.FC<BackofficeViewProps> = ({ catalog, onAddProduct, onRemoveProduct, onUpdateProduct }) => {
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<Product | null>(null);

  const handleEditClick = (product: Product) => {
    setEditingId(product.id);
    setEditForm({ ...product });
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setEditForm(null);
  };

  const handleSaveEdit = () => {
    if (editForm) {
      onUpdateProduct(editForm);
      setEditingId(null);
      setEditForm(null);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (!editForm) return;
    const { name, value } = e.target;

    const isFloat = name.includes('Power');
    const isInt = name === 'id' || name === 'channels' || name.includes('Address');

    let parsedValue: any = value;
    if (isFloat) parsedValue = parseFloat(value) || 0;
    if (isInt) parsedValue = parseInt(value) || 0;

    if (name === 'category') {
        const newCategory = value as ProductCategory;
        const availableTypes = getTypesForCategory(newCategory);
        setEditForm({
            ...editForm,
            category: newCategory,
            type: availableTypes[0] || ''
        });
    } else {
        setEditForm(prev => prev ? ({ ...prev, [name]: parsedValue }) : null);
    }
  };

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-6 pb-4 border-b border-slate-100">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-brand-50 rounded-lg">
                <Database className="text-brand-600" size={20} />
            </div>
            <h2 className="text-xl font-bold text-slate-800">Product Management (Backoffice)</h2>
          </div>
          <button
            onClick={onAddProduct}
            className="bg-brand-600 hover:bg-brand-700 text-white font-medium py-2 px-4 rounded-lg shadow-sm text-sm flex items-center gap-2 transition-colors"
          >
            <Plus size={16} /> New Product
          </button>
        </div>

        <div className="overflow-x-auto border border-slate-200 rounded-lg shadow-sm">
          <table className="w-full text-left text-sm border-collapse">
            <thead className="bg-slate-50 text-slate-500 uppercase font-semibold text-xs tracking-wider">
              <tr>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-slate-200 bg-slate-50 w-20">ID</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-slate-200 bg-slate-50 w-24">Brand</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-slate-200 bg-slate-50 min-w-[120px]">Model</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-slate-200 bg-slate-50 w-32">Category</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-slate-200 bg-slate-50 w-28">Type</th>
                <th rowSpan={2} className="px-2 py-3 border-b border-r border-slate-200 bg-slate-50 text-center w-16">Ch</th>
                <th colSpan={2} className="px-2 py-2 border-b border-r border-slate-200 bg-slate-100/50 text-center text-slate-600">Supplies</th>
                <th colSpan={2} className="px-2 py-2 border-b border-r border-slate-200 bg-slate-100/50 text-center text-slate-600">Consumes</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-slate-200 bg-slate-50 w-20 text-center">Actions</th>
              </tr>
              <tr>
                <th className="px-2 py-1 border-b border-r border-slate-200 bg-slate-50 text-center text-[10px]">Pwr</th>
                <th className="px-2 py-1 border-b border-r border-slate-200 bg-slate-50 text-center text-[10px]">Addr</th>
                <th className="px-2 py-1 border-b border-r border-slate-200 bg-slate-50 text-center text-[10px]">Pwr</th>
                <th className="px-2 py-1 border-b border-slate-200 bg-slate-50 text-center text-[10px]">Addr</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {catalog.map((product) => {
                const isEditing = editingId === product.id;
                const data = isEditing && editForm ? editForm : product;

                return (
                  <tr key={product.id} className={`hover:bg-slate-50 transition-colors ${isEditing ? 'bg-brand-50/20' : ''}`}>
                    <td className="px-3 py-2 border-r border-slate-100 font-mono text-xs font-medium text-slate-500">
                        {isEditing ? (
                            <input 
                                type="number" 
                                name="id" 
                                value={data.id} 
                                onChange={handleInputChange} 
                                className={INPUT_CLASS} 
                            />
                        ) : data.id}
                    </td>

                    <td className="px-3 py-2 border-r border-slate-100 text-slate-600">
                        {isEditing ? (
                            <select name="brand" value={data.brand} onChange={handleInputChange} className={SELECT_CLASS}>
                                <option value="ROEHN">ROEHN</option>
                            </select>
                        ) : data.brand}
                    </td>

                    <td className="px-3 py-2 border-r border-slate-100 font-medium text-slate-900">
                        {isEditing ? (
                            <input 
                                type="text" 
                                name="model" 
                                value={data.model} 
                                onChange={handleInputChange} 
                                className={INPUT_CLASS} 
                            />
                        ) : data.model}
                    </td>

                    <td className="px-3 py-2 border-r border-slate-100 text-xs text-slate-600">
                        {isEditing ? (
                            <select name="category" value={data.category} onChange={handleInputChange} className={SELECT_CLASS}>
                                {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                            </select>
                        ) : data.category}
                    </td>

                    <td className="px-3 py-2 border-r border-slate-100 text-xs text-slate-600">
                         {isEditing ? (
                            <select name="type" value={data.type} onChange={handleInputChange} className={SELECT_CLASS}>
                                {getTypesForCategory(data.category).map(t => <option key={t} value={t}>{t}</option>)}
                            </select>
                        ) : data.type}
                    </td>

                    <td className="px-3 py-2 border-r border-slate-100 text-center font-semibold text-slate-700">
                        {isEditing ? (
                            <input type="number" name="channels" value={data.channels} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : data.channels}
                    </td>

                    <td className="px-3 py-2 border-r border-slate-100 text-center text-slate-500 text-xs">
                        {isEditing ? (
                            <input type="number" step="0.1" name="suppliesPower" value={data.suppliesPower} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.suppliesPower > 0 ? <span className="text-emerald-600 font-medium">{data.suppliesPower}</span> : '-')}
                    </td>

                    <td className="px-3 py-2 border-r border-slate-100 text-center text-slate-500 text-xs">
                        {isEditing ? (
                            <input type="number" name="suppliesAddress" value={data.suppliesAddress} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.suppliesAddress > 0 ? <span className="text-emerald-600 font-medium">{data.suppliesAddress}</span> : '-')}
                    </td>

                    <td className="px-3 py-2 border-r border-slate-100 text-center text-slate-500 text-xs">
                        {isEditing ? (
                            <input type="number" step="0.1" name="consumesPower" value={data.consumesPower} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.consumesPower > 0 ? <span className="text-amber-600">{data.consumesPower}</span> : '-')}
                    </td>

                    <td className="px-3 py-2 border-b border-slate-100 text-center text-slate-500 text-xs">
                        {isEditing ? (
                            <input type="number" name="consumesAddress" value={data.consumesAddress} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.consumesAddress > 0 ? <span className="text-amber-600">{data.consumesAddress}</span> : '-')}
                    </td>

                    <td className="px-3 py-2 border-b border-slate-100 text-center">
                        <div className="flex items-center justify-center gap-2">
                            {isEditing ? (
                                <>
                                    <button onClick={handleSaveEdit} className="text-emerald-500 hover:text-emerald-700 transition-colors p-1" title="Save">
                                        <Save size={18} />
                                    </button>
                                    <button onClick={handleCancelEdit} className="text-slate-400 hover:text-slate-600 transition-colors p-1" title="Cancel">
                                        <X size={18} />
                                    </button>
                                </>
                            ) : (
                                <>
                                    <button onClick={() => handleEditClick(product)} className="text-brand-400 hover:text-brand-600 transition-colors p-1" title="Edit">
                                        <Pencil size={16} />
                                    </button>
                                    <button onClick={() => onRemoveProduct(product.id)} className="text-slate-300 hover:text-red-500 transition-colors p-1" title="Remove">
                                        <Trash2 size={16} />
                                    </button>
                                </>
                            )}
                        </div>
                    </td>
                  </tr>
                );
              })}
              {catalog.length === 0 && (
                <tr>
                  <td colSpan={11} className="px-6 py-12 text-center text-slate-400">
                    <div className="flex flex-col items-center gap-2">
                        <Database size={32} className="opacity-20" />
                        <p>No products found. Click "New Product" to begin.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="mt-4 flex items-center justify-between text-xs text-slate-400">
           <div className="flex items-center gap-2">
            <Save size={14} />
            <span>Changes must be saved using the disk icon for each row.</span>
           </div>
           <div>
            {catalog.length} products in database
           </div>
        </div>
      </div>
    </div>
  );
};

