          </nav>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 mt-8">

        {view === 'backoffice' ? (
          <BackofficeView 
            catalog={catalog} 
            onAddProduct={handleAddProduct} 
            onRemoveProduct={handleRemoveProduct}
            onUpdateProduct={handleUpdateProduct}
          />
        ) : (
          <>
            {result ? (
              <ResultView data={result} onReset={() => setResult(null)} />
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-fade-in">
                <div className="lg:col-span-1 space-y-6">
                  <div>
                    <h2 className="text-2xl font-bold text-slate-900 mb-2">New Project</h2>
                    <p className="text-slate-600">
                      Enter project details. The system will use the <strong className="text-brand-600">{catalog.length} active products</strong> in the catalog to calculate the BOM automatically.
                    </p>
                  </div>

                  <div className="p-4 bg-brand-50 rounded-xl border border-brand-100">
                    <h3 className="font-semibold text-brand-800 mb-2 flex items-center gap-2">
                      <LayoutTemplate size={18} />
