                    </h3>
                    <ul className="text-sm text-brand-700 space-y-2 list-disc list-inside">
                      <li>Configure products in Backoffice</li>
                      <li>Count customer devices here</li>
                      <li>Get a BOM calculated by rules</li>
                    </ul>
                  </div>
                </div>

                <form onSubmit={handleSubmit} className="lg:col-span-2 space-y-8">
                  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Project Name</label>
                        <input
                          required
                          type="text"
                          name="projectName"
                          placeholder="e.g. Smith Residence"
                          value={inputs.projectName}
                          onChange={handleTextChange}
                          className="w-full px-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none transition-all"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Lead Integrator</label>
                        <input
                          required
