                </form>
              </div>
            )}
          </>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Product, ProductCategory } from '../types';
import { Plus, Trash2, Database, Save, X, Pencil } from 'lucide-react';

interface BackofficeViewProps {
  catalog: Product[];
  onAddProduct: () => void;
  onRemoveProduct: (id: number) => void;
  onUpdateProduct: (product: Product) => void;
}

const CATEGORIES: ProductCategory[] = ['Processor', 'Lighting Control', 'Shades Control', 'HVAC Control', 'Power Supply', 'Keypad', 'Sensor'];

const getTypesForCategory = (cat: ProductCategory): string[] => {
  switch (cat) {
    case 'Processor': return ['Processor'];
    case 'Lighting Control': return ['On/Off', 'Dimmer', 'PWM', 'DALI'];
    case 'Shades Control': return ['Wired', 'Wireless'];
    case 'HVAC Control': return ['Infrared', 'VRV/VRF'];
    case 'Power Supply': return ['Bus Power', 'Auxiliary'];
    case 'Keypad': return ['Standard', 'Touch', 'Thermostat'];
    case 'Sensor': return ['Motion', 'Presence', 'Lux', 'Temp'];
    default: return ['Standard'];
  }
};

const INPUT_CLASS = "w-full bg-white border border-slate-200 rounded px-2 py-1.5 text-xs text-slate-700 focus:border-brand-500 focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-sm";
const SELECT_CLASS = "w-full bg-white border border-slate-200 rounded px-1 py-1.5 text-xs text-slate-700 focus:border-brand-500 focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-sm";

export const BackofficeView: React.FC<BackofficeViewProps> = ({ catalog, onAddProduct, onRemoveProduct, onUpdateProduct }) => {
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<Product | null>(null);

  const handleEditClick = (product: Product) => {
    setEditingId(product.id);
    setEditForm({ ...product });
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setEditForm(null);
  };

  const handleSaveEdit = () => {
    if (editForm) {
      onUpdateProduct(editForm);
      setEditingId(null);
      setEditForm(null);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (!editForm) return;
    const { name, value } = e.target;

    const isFloat = name.includes('Power');
    const isInt = name === 'id' || name === 'channels' || name.includes('Address');

    let parsedValue: any = value;
    if (isFloat) parsedValue = parseFloat(value) || 0;
    if (isInt) parsedValue = parseInt(value) || 0;

    if (name === 'category') {
        const newCategory = value as ProductCategory;
        const availableTypes = getTypesForCategory(newCategory);
        setEditForm({
            ...editForm,
            category: newCategory,
            type: availableTypes[0] || ''
        });
    } else {
        setEditForm(prev => prev ? ({ ...prev, [name]: parsedValue }) : null);
    }
  };

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-6 pb-4 border-b border-slate-100">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-brand-50 rounded-lg">
                <Database className="text-brand-600" size={20} />
            </div>
            <h2 className="text-xl font-bold text-slate-800">Product Management (Backoffice)</h2>
          </div>
          <button
            onClick={onAddProduct}
            className="bg-brand-600 hover:bg-brand-700 text-white font-medium py-2 px-4 rounded-lg shadow-sm text-sm flex items-center gap-2 transition-colors"
          >
            <Plus size={16} /> New Product
          </button>
        </div>

        <div className="overflow-x-auto border border-slate-200 rounded-lg shadow-sm">
          <table className="w-full text-left text-sm border-collapse">
            <thead className="bg-slate-50 text-slate-500 uppercase font-semibold text-xs tracking-wider">
              <tr>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-slate-200 bg-slate-50 w-20">ID</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-slate-200 bg-slate-50 w-24">Brand</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-slate-200 bg-slate-50 min-w-[120px]">Model</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-slate-200 bg-slate-50 w-32">Category</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-slate-200 bg-slate-50 w-28">Type</th>
                <th rowSpan={2} className="px-2 py-3 border-b border-r border-slate-200 bg-slate-50 text-center w-16">Ch</th>
                <th colSpan={3} className="px-2 py-2 border-b border-r border-slate-200 bg-slate-100/50 text-center text-slate-600">Supplies</th>
                <th colSpan={3} className="px-2 py-2 border-b border-r border-slate-200 bg-slate-100/50 text-center text-slate-600">Consumes</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-slate-200 bg-slate-50 w-20 text-center">Actions</th>
              </tr>
              <tr>
                <th className="px-2 py-1 border-b border-r border-slate-200 bg-slate-50 text-center text-[10px]">LPwr</th>
                <th className="px-2 py-1 border-b border-r border-slate-200 bg-slate-50 text-center text-[10px]">NPwr</th>
                <th className="px-2 py-1 border-b border-r border-slate-200 bg-slate-50 text-center text-[10px]">Addr</th>
                <th className="px-2 py-1 border-b border-r border-slate-200 bg-slate-50 text-center text-[10px]">LPwr</th>
                <th className="px-2 py-1 border-b border-r border-slate-200 bg-slate-50 text-center text-[10px]">NPwr</th>
                <th className="px-2 py-1 border-b border-slate-200 bg-slate-50 text-center text-[10px]">Addr</th>
