                        ) : (data.suppliesLPower > 0 ? <span className="text-emerald-600 font-medium">{data.suppliesLPower}</span> : '-')}
                    </td>
                    <td className="px-3 py-2 border-r border-slate-100 text-center text-slate-500 text-xs">
                        {isEditing ? (
                            <input type="number" step="0.1" name="suppliesNPower" value={data.suppliesNPower} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
