                    </td>
                    <td className="px-3 py-2 border-r border-slate-100 text-center text-slate-500 text-xs">
                        {isEditing ? (
                            <input type="number" step="0.1" name="consumesNPower" value={data.consumesNPower} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.consumesNPower > 0 ? <span className="text-amber-600">{data.consumesNPower}</span> : '-')}
                    </td>
                    <td className="px-3 py-2 border-b border-slate-100 text-center text-slate-500 text-xs">
                        {isEditing ? (
                            <input type="number" name="consumesAddress" value={data.consumesAddress} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.consumesAddress > 0 ? <span className="text-amber-600">{data.consumesAddress}</span> : '-')}
                    </td>

                    <td className="px-3 py-2 border-b border-slate-100 text-center">
                        <div className="flex items-center justify-center gap-2">
                            {isEditing ? (
