      id: 'SHADE_WIRELESS_GROUP',
      types: [DeviceType.SHADE_WIRELESS],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wireless', 'GTW'],
      bomCategory: 'Shading' as const
    },
    {
      id: 'HVAC_IR_GROUP',
      types: [DeviceType.CLIMATE_IR],
      targetCategory: 'HVAC Control',
      typeKeywords: ['IR', 'Infrared', 'Emitter', 'SA1'],
      bomCategory: 'Climate' as const
    },
    {
      id: 'HVAC_CENTRAL_GROUP',
      types: [DeviceType.CLIMATE_VRV],
      targetCategory: 'HVAC Control',
      typeKeywords: ['VRV', 'VRF', 'Gateway', 'Thermostat', 'DK'],
      bomCategory: 'Climate' as const
    }
  ];

  // --- Module Calculation ---
  INF_GROUPS.forEach(group => {
    const totalLoad = group.types.reduce((sum, type) => sum + (activeCounts[type] || 0), 0);
    if (totalLoad <= 0) return;

    const candidates = catalog.filter(p => 
      p.category === group.targetCategory && 
      group.typeKeywords.some(k => 
        p.type.toLowerCase().includes(k.toLowerCase()) || 
        p.model.toLowerCase().includes(k.toLowerCase())
      )
    );

    if (candidates.length === 0) {
      items.push({
        sku: 'MISSING-PRODUCT',
        name: `Incompatible: ${group.id}`,
        description: `No catalog products found to control ${totalLoad} devices.`,
        quantity: 0,
        category: 'Accessory',
        reasoning: `Error: Missing ${group.targetCategory} products in Backoffice.`
      });
      return;
    }

    const optimization = getOptimizedBom(totalLoad, candidates, (p) => p.channels);

    optimization.forEach((qty, product) => {
        items.push({
          sku: product.model,
          name: `${product.brand} ${product.type}`,
          description: `${product.category} (${product.channels} Channels)`,
          quantity: qty,
          category: group.bomCategory,
          reasoning: `Generic Optimization: Total ${totalLoad} loads. ${product.channels}-ch modules selected.`
        });
    });
  });

  // --- Power Calculation Helper ---
  const calculatePowerStats = (currentItems: BomItem[]) => {
    let totals = { consumedL: 0, suppliedL: 0, consumedN: 0, suppliedN: 0 };
    currentItems.forEach(item => {
        const p = catalog.find(cp => cp.model === item.sku);
        if (p) {
            totals.consumedL += p.consumesLPower * item.quantity;
            totals.consumedN += p.consumesNPower * item.quantity;
            totals.suppliedL += p.suppliesLPower * item.quantity;
            totals.suppliedN += p.suppliesNPower * item.quantity;
        }
    });
    return totals;
  };

  // 1. Resolve NPower (Network Power)
  // Modules usually consume NPower. Processor supplies it.
  let stats = calculatePowerStats(items);
  let deficitN = stats.consumedN - stats.suppliedN;

  if (deficitN > 0) {
      // Find products that supply NPower.
      const nCandidates = catalog.filter(p => p.suppliesNPower > 0);

      if (nCandidates.length === 0) {
          items.push({
            sku: 'MISSING-N-PWR',
            name: 'Network Power Deficit',
            description: `System needs ${deficitN.toFixed(2)} units of NPower.`,
            quantity: 1,
            category: 'Accessory',
            reasoning: 'Error: No device found to supply Network Power.'
          });
      } else {
          const nBom = getOptimizedBom(deficitN, nCandidates, (p) => p.suppliesNPower);

          nBom.forEach((qty, product) => {
              items.push({
                  sku: product.model,
                  name: `${product.brand} ${product.type}`,
                  description: `Network Power Supply`,
                  quantity: qty,
                  category: 'Accessory',
                  reasoning: `NPower Deficit: ${deficitN.toFixed(2)}. Added to supply network power.`
              });
          });
      }
  }

  // --- Rule: Every Processor needs a dedicated Power Supply ---
  const processorsInBom = items.filter(item => {
      const p = catalog.find(cp => cp.model === item.sku);
      return p?.category === 'Processor';
  });
  const totalProcessors = processorsInBom.reduce((sum, item) => sum + item.quantity, 0);

  if (totalProcessors > 0) {
      // Find the best power supply (highest LPower output) to pair with processors
      const psCandidates = catalog
          .filter(p => p.category === 'Power Supply' && p.suppliesLPower > 0)
          .sort((a, b) => b.suppliesLPower - a.suppliesLPower);

      if (psCandidates.length > 0) {
          const primaryPS = psCandidates[0];
          items.push({
              sku: primaryPS.model,
              name: `${primaryPS.brand} ${primaryPS.type}`,
              description: `Dedicated Power Supply`,
              quantity: totalProcessors,
              category: 'Accessory',
              reasoning: `Rule: Dedicated Power Supply per Processor (${totalProcessors} units).`
          });
      } else {
           items.push({
            sku: 'MISSING-PWR-SUPPLY',
            name: 'Power Supply Missing',
            description: `No Power Supply found in catalog for processors.`,
            quantity: totalProcessors,
            category: 'Accessory',
            reasoning: 'Error: Processor requires Power Supply but none found.'
          });
      }
  }

  // 2. Resolve LPower (Logic/Line Power)
  // Logic: 
  // - Processors and their Dedicated Power Supplies are excluded from the general bus calculation (reserved pair).
  // - We calculate the load of all OTHER modules.
  // - If there is any load, we check if we have general power supplies available (unlikely unless added).
  // - We add Power Supplies to cover the module load.

  let moduleLoadL = 0;
  let availableGeneralL = 0;

  items.forEach(item => {
    const p = catalog.find(cp => cp.model === item.sku);
    if (!p) return;

    const isProcessor = p.category === 'Processor';
    // Identify the dedicated PS by its unique reasoning tag added in the previous step
    const isDedicatedPS = item.reasoning?.includes('Dedicated Power Supply');

    if (isProcessor) {
        // Processor load is covered by its dedicated supply. Ignore.
    } else if (isDedicatedPS) {
        // Dedicated supply is reserved for processor. Ignore capacity.
    } else {
        // This is a module or a general accessory.
        moduleLoadL += p.consumesLPower * item.quantity;
        availableGeneralL += p.suppliesLPower * item.quantity;
    }
  });

  let deficitL = moduleLoadL - availableGeneralL;

  if (deficitL > 0) {
      const lCandidates = catalog.filter(p => p.suppliesLPower > 0);

      if (lCandidates.length === 0) {
           items.push({
            sku: 'MISSING-L-PWR',
            name: 'Line Power Deficit',
            description: `Modules need ${deficitL.toFixed(2)} units of LPower (excluding processors).`,
            quantity: 1,
            category: 'Accessory',
            reasoning: 'Error: No device found to supply Line Power.'
          });
      } else {
          const lBom = getOptimizedBom(deficitL, lCandidates, (p) => p.suppliesLPower);

          lBom.forEach((qty, product) => {
              items.push({
                  sku: product.model,
                  name: `${product.brand} ${product.type}`,
                  description: `Line Power Supply`,
                  quantity: qty,
                  category: 'Accessory',
                  reasoning: `Module LPower Load: ${deficitL.toFixed(2)}. Added to supply bus power.`
              });
          });
      }
  }

  const totalDevices = Object.values(activeCounts).reduce((a, b) => a + b, 0);

  // Final calculation for display purposes only (showing total system specs)
  const finalStats = calculatePowerStats(items);

  return {
    items,
    totalDevices,
    summary: `Technical specification generated. Hardware selected for ${totalDevices} endpoints. Power analysis: LPower Load ${finalStats.consumedL.toFixed(1)}/${finalStats.suppliedL.toFixed(1)} (Reserved + General), NPower Load ${finalStats.consumedN.toFixed(1)}/${finalStats.suppliedN.toFixed(1)}.`
  };
};

