        },
        nPower: {
            consumed: finalStats.consumedN,
            supplied: finalStats.suppliedN
        }
    },
    addressStats: {
        consumed: finalStats.consumedAddr,
        supplied: finalStats.suppliedAddr
    },
    categoryCounts
  };
};

