import React from 'react';
import { Plus, Minus } from 'lucide-react';

interface CounterInputProps {
  label: string;
  value: number;
  onChange: (val: number) => void;
  icon?: React.ReactNode;
}

export const CounterInput: React.FC<CounterInputProps> = ({ label, value, onChange, icon }) => {
  const handleIncrement = () => onChange(value + 1);
  const handleDecrement = () => onChange(Math.max(0, value - 1));

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let newValue = parseInt(e.target.value, 10);
    if (isNaN(newValue)) newValue = 0;
    onChange(Math.max(0, newValue));
  };

  const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    e.target.select();
  };

  return (
    <div className="flex items-center justify-between p-4 bg-white border border-gray-200 rounded-lg shadow-sm hover:border-brand-500 transition-colors">
      <div className="flex items-center gap-3">
        {icon && <div className="text-brand-600">{icon}</div>}
        <span className="font-medium text-gray-700">{label}</span>
      </div>
      <div className="flex items-center gap-3">
        <button
          onClick={handleDecrement}
          disabled={value === 0}
          className="p-1 rounded-full hover:bg-gray-100 disabled:opacity-30 text-gray-500 transition-colors"
          type="button"
          tabIndex={-1}
        >
          <Minus size={20} />
        </button>
        <input
          type="number"
          min="0"
          value={value.toString()}
          onChange={handleInputChange}
          onFocus={handleFocus}
          className="w-16 text-center font-bold text-lg text-gray-900 outline-none border-b-2 border-transparent focus:border-brand-500 transition-all bg-transparent [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
        />
        <button
          onClick={handleIncrement}
          className="p-1 rounded-full hover:bg-brand-50 text-brand-600 transition-colors"
          type="button"
          tabIndex={-1}
        >
          <Plus size={20} />
        </button>
      </div>
    </div>
  );
};

