                                        <Pencil size={16} />
                                    </button>
                                    <button onClick={() => onRemoveProduct(product.id)} className="text-gray-300 hover:text-red-500 transition-colors p-1" title="Remove">
                                        <Trash2 size={16} />
                                    </button>
                                </>
                            )}
                        </div>
                    </td>
                  </tr>
                );
              })}
              {catalog.length === 0 && (
                <tr>
                  <td colSpan={13} className="px-6 py-12 text-center text-gray-400">
                    <div className="flex flex-col items-center gap-2">
                        <Database size={32} className="opacity-20" />
                        <p>No products found. Click "New Product" to begin.</p>
