              )}
            </tbody>
          </table>
        </div>
        <div className="mt-4 flex items-center justify-between text-xs text-gray-400">
           <div className="flex items-center gap-2">
            <Save size={14} />
            <span>Changes must be saved using the disk icon for each row.</span>
