  [DeviceType.LIGHT_DALI]: 'DALI Addresses/Groups',
  [DeviceType.SHADE_WIRED]: 'Wired Shades',
  [DeviceType.SHADE_WIRELESS]: 'Wireless Shades',
  [DeviceType.CLIMATE_IR]: 'Infrared Control (Split)',
  [DeviceType.CLIMATE_VRV]: 'VRV/VRF Control (Gateway)',
  [DeviceType.KEYPAD_QUANTICA_K]: 'Quantica K Keypads',
  [DeviceType.KEYPAD_QUANTICA_L]: 'Quantica L Keypads',
  [DeviceType.KEYPAD_QUANTICA_P]: 'Quantica P Keypads',
  [DeviceType.KEYPAD_ION]: 'ION Keypads',
