interface BackofficeViewProps {
  catalog: Product[];
  onAddProduct: () => void;
  onRemoveProduct: (id: number) => void;
  onUpdateProduct: (product: Product) => void;
}

const CATEGORIES: ProductCategory[] = ['Processor', 'Lighting Control', 'Shades Control', 'HVAC Control', 'Power Supply', 'Keypad', 'Sensor'];

const getTypesForCategory = (cat: ProductCategory): string[] => {
  switch (cat) {
    case 'Processor': return ['Processor'];
    case 'Lighting Control': return ['On/Off', 'Dimmer', 'PWM', 'DALI'];
    case 'Shades Control': return ['Wired', 'Wireless'];
    case 'HVAC Control': return ['Infrared', 'VRV/VRF'];
    case 'Power Supply': return ['Bus Power', 'Auxiliary'];
    case 'Keypad': return ['Standard', 'Touch', 'Thermostat', 'Quantica K', 'Quantica L', 'Quantica P', 'ION'];
    case 'Sensor': return ['Motion', 'Presence', 'Lux', 'Temp', 'Widelux', 'X-Ray'];
    default: return ['Standard'];
  }
};

const INPUT_CLASS = "w-full bg-white border border-gray-200 rounded px-2 py-1.5 text-xs text-gray-700 focus:border-brand-500 focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-sm";
const SELECT_CLASS = "w-full bg-white border border-gray-200 rounded px-1 py-1.5 text-xs text-gray-700 focus:border-brand-500 focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-sm";

export const BackofficeView: React.FC<BackofficeViewProps> = ({ catalog, onAddProduct, onRemoveProduct, onUpdateProduct }) => {
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<Product | null>(null);

  const handleEditClick = (product: Product) => {
    setEditingId(product.id);
    setEditForm({ ...product });
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setEditForm(null);
  };

  const handleSaveEdit = () => {
    if (editForm) {
      onUpdateProduct(editForm);
      setEditingId(null);
      setEditForm(null);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (!editForm) return;
    const { name, value } = e.target;

    const isFloat = name.includes('Power');
    const isInt = name === 'id' || name === 'channels' || name.includes('Address');

    let parsedValue: any = value;
    if (isFloat) parsedValue = parseFloat(value) || 0;
    if (isInt) parsedValue = parseInt(value) || 0;

    if (name === 'category') {
        const newCategory = value as ProductCategory;
        const availableTypes = getTypesForCategory(newCategory);
        setEditForm({
            ...editForm,
            category: newCategory,
            type: availableTypes[0] || ''
        });
    } else {
        setEditForm(prev => prev ? ({ ...prev, [name]: parsedValue }) : null);
    }
  };

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
        <div className="flex items-center justify-between mb-6 pb-4 border-b border-gray-100">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-brand-50 rounded-lg">
                <Database className="text-brand-600" size={20} />
            </div>
            <h2 className="text-xl font-bold text-gray-800">Product Management (Backoffice)</h2>
          </div>
          <button
            onClick={onAddProduct}
            className="bg-brand-600 hover:bg-brand-700 text-white font-medium py-2 px-4 rounded-lg shadow-sm text-sm flex items-center gap-2 transition-colors"
          >
            <Plus size={16} /> New Product
          </button>
        </div>

        <div className="overflow-x-auto border border-gray-200 rounded-lg shadow-sm">
          <table className="w-full text-left text-sm border-collapse">
            <thead className="bg-gray-50 text-gray-500 uppercase font-semibold text-xs tracking-wider">
              <tr>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-gray-200 bg-gray-50 w-20">ID</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-gray-200 bg-gray-50 w-24">Brand</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-gray-200 bg-gray-50 min-w-[120px]">Model</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-gray-200 bg-gray-50 w-32">Category</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-r border-gray-200 bg-gray-50 w-28">Type</th>
                <th rowSpan={2} className="px-2 py-3 border-b border-r border-gray-200 bg-gray-50 text-center w-16">Ch</th>
                <th colSpan={3} className="px-2 py-2 border-b border-r border-gray-200 bg-gray-100/50 text-center text-gray-600">Supplies</th>
                <th colSpan={3} className="px-2 py-2 border-b border-r border-gray-200 bg-gray-100/50 text-center text-gray-600">Consumes</th>
                <th rowSpan={2} className="px-4 py-3 border-b border-gray-200 bg-gray-50 w-20 text-center">Actions</th>
              </tr>
              <tr>
                <th className="px-2 py-1 border-b border-r border-gray-200 bg-gray-50 text-center text-[10px]">LPwr</th>
                <th className="px-2 py-1 border-b border-r border-gray-200 bg-gray-50 text-center text-[10px]">NPwr</th>
                <th className="px-2 py-1 border-b border-r border-gray-200 bg-gray-50 text-center text-[10px]">Addr</th>
                <th className="px-2 py-1 border-b border-r border-gray-200 bg-gray-50 text-center text-[10px]">LPwr</th>
                <th className="px-2 py-1 border-b border-r border-gray-200 bg-gray-50 text-center text-[10px]">NPwr</th>
                <th className="px-2 py-1 border-b border-gray-200 bg-gray-50 text-center text-[10px]">Addr</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {catalog.map((product) => {
                const isEditing = editingId === product.id;
                const data = isEditing && editForm ? editForm : product;

                return (
                  <tr key={product.id} className={`hover:bg-gray-50 transition-colors ${isEditing ? 'bg-brand-50/20' : ''}`}>
                    <td className="px-3 py-2 border-r border-gray-100 font-mono text-xs font-medium text-gray-500">
                        {isEditing ? (
                            <input 
                                type="number" 
                                name="id" 
                                value={data.id} 
                                onChange={handleInputChange} 
                                className={INPUT_CLASS} 
                            />
                        ) : data.id}
                    </td>

                    <td className="px-3 py-2 border-r border-gray-100 text-gray-600">
                        {isEditing ? (
                            <select name="brand" value={data.brand} onChange={handleInputChange} className={SELECT_CLASS}>
                                <option value="ROEHN">ROEHN</option>
                            </select>
                        ) : data.brand}
                    </td>

                    <td className="px-3 py-2 border-r border-gray-100 font-medium text-gray-900">
                        {isEditing ? (
                            <input 
                                type="text" 
                                name="model" 
                                value={data.model} 
                                onChange={handleInputChange} 
                                className={INPUT_CLASS} 
                            />
                        ) : data.model}
                    </td>

                    <td className="px-3 py-2 border-r border-gray-100 text-xs text-gray-600">
                        {isEditing ? (
                            <select name="category" value={data.category} onChange={handleInputChange} className={SELECT_CLASS}>
                                {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                            </select>
                        ) : data.category}
                    </td>

                    <td className="px-3 py-2 border-r border-gray-100 text-xs text-gray-600">
                         {isEditing ? (
                            <select name="type" value={data.type} onChange={handleInputChange} className={SELECT_CLASS}>
                                {getTypesForCategory(data.category).map(t => <option key={t} value={t}>{t}</option>)}
                            </select>
                        ) : data.type}
                    </td>

                    <td className="px-3 py-2 border-r border-gray-100 text-center font-semibold text-gray-700">
                        {isEditing ? (
                            <input type="number" name="channels" value={data.channels} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : data.channels}
                    </td>

                    {/* Supplies Columns */}
                    <td className="px-3 py-2 border-r border-gray-100 text-center text-gray-500 text-xs">
                        {isEditing ? (
                            <input type="number" step="0.1" name="suppliesLPower" value={data.suppliesLPower} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.suppliesLPower > 0 ? <span className="text-emerald-600 font-medium">{data.suppliesLPower}</span> : '-')}
                    </td>
                    <td className="px-3 py-2 border-r border-gray-100 text-center text-gray-500 text-xs">
                        {isEditing ? (
                            <input type="number" step="0.1" name="suppliesNPower" value={data.suppliesNPower} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.suppliesNPower > 0 ? <span className="text-emerald-600 font-medium">{data.suppliesNPower}</span> : '-')}
                    </td>
                    <td className="px-3 py-2 border-r border-gray-100 text-center text-gray-500 text-xs">
                        {isEditing ? (
                            <input type="number" name="suppliesAddress" value={data.suppliesAddress} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.suppliesAddress > 0 ? <span className="text-emerald-600 font-medium">{data.suppliesAddress}</span> : '-')}
                    </td>

                    {/* Consumes Columns */}
                    <td className="px-3 py-2 border-r border-gray-100 text-center text-gray-500 text-xs">
                        {isEditing ? (
                            <input type="number" step="0.1" name="consumesLPower" value={data.consumesLPower} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.consumesLPower > 0 ? <span className="text-amber-600">{data.consumesLPower}</span> : '-')}
                    </td>
                    <td className="px-3 py-2 border-r border-gray-100 text-center text-gray-500 text-xs">
                        {isEditing ? (
                            <input type="number" step="0.1" name="consumesNPower" value={data.consumesNPower} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.consumesNPower > 0 ? <span className="text-amber-600">{data.consumesNPower}</span> : '-')}
                    </td>
                    <td className="px-3 py-2 border-b border-gray-100 text-center text-gray-500 text-xs">
                        {isEditing ? (
                            <input type="number" name="consumesAddress" value={data.consumesAddress} onChange={handleInputChange} className={`${INPUT_CLASS} text-center`} />
                        ) : (data.consumesAddress > 0 ? <span className="text-amber-600">{data.consumesAddress}</span> : '-')}
                    </td>

                    <td className="px-3 py-2 border-b border-gray-100 text-center">
                        <div className="flex items-center justify-center gap-2">
                            {isEditing ? (
                                <>
                                    <button onClick={handleSaveEdit} className="text-emerald-500 hover:text-emerald-700 transition-colors p-1" title="Save">
                                        <Save size={18} />
                                    </button>
                                    <button onClick={handleCancelEdit} className="text-gray-400 hover:text-gray-600 transition-colors p-1" title="Cancel">
                                        <X size={18} />
                                    </button>
                                </>
                            ) : (
                                <>
                                    <button onClick={() => handleEditClick(product)} className="text-brand-400 hover:text-brand-600 transition-colors p-1" title="Edit">
                                        <Pencil size={16} />
                                    </button>
                                    <button onClick={() => onRemoveProduct(product.id)} className="text-gray-300 hover:text-red-500 transition-colors p-1" title="Remove">
                                        <Trash2 size={16} />
                                    </button>
                                </>
                            )}
                        </div>
                    </td>
                  </tr>
                );
              })}
              {catalog.length === 0 && (
                <tr>
                  <td colSpan={13} className="px-6 py-12 text-center text-gray-400">
                    <div className="flex flex-col items-center gap-2">
                        <Database size={32} className="opacity-20" />
                        <p>No products found. Click "New Product" to begin.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="mt-4 flex items-center justify-between text-xs text-gray-400">
           <div className="flex items-center gap-2">
            <Save size={14} />
            <span>Changes must be saved using the disk icon for each row.</span>
           </div>
           <div>
            {catalog.length} products in database
           </div>
        </div>
      </div>
    </div>
  );
};

export enum DeviceType {
  // Lighting
  LIGHT_ONOFF = 'LIGHT_ONOFF',
  LIGHT_DIMMER = 'LIGHT_DIMMER',
  LIGHT_PWM = 'LIGHT_PWM',
  LIGHT_DALI = 'LIGHT_DALI',
  // Shades
  SHADE_WIRED = 'SHADE_WIRED',
  SHADE_WIRELESS = 'SHADE_WIRELESS',
  // Climate
  CLIMATE_IR = 'CLIMATE_IR',
  CLIMATE_VRV = 'CLIMATE_VRV',
  // Keypads / User Interfaces
  KEYPAD_QUANTICA_K = 'KEYPAD_QUANTICA_K',
  KEYPAD_QUANTICA_L = 'KEYPAD_QUANTICA_L',
  KEYPAD_QUANTICA_P = 'KEYPAD_QUANTICA_P',
  KEYPAD_ION = 'KEYPAD_ION',
  // Sensors
  SENSOR_WIDELUX = 'SENSOR_WIDELUX',
  SENSOR_XRAY = 'SENSOR_XRAY',
}

export type ProductCategory = 'Processor' | 'Lighting Control' | 'Shades Control' | 'HVAC Control' | 'Power Supply' | 'Keypad' | 'Sensor';

export interface Product {
  id: number;
  category: ProductCategory;
  type: string;
  brand: string;
  model: string;
  channels: number; // Capacity
  suppliesLPower: number; // Renamed from suppliesPower
  suppliesNPower: number; // New: Network Power
  suppliesAddress: number;
  suppliesPNETPorts: number; // New: PNET Ports
  consumesLPower: number; // Renamed from consumesPower
  consumesNPower: number; // New: Network Power
  consumesAddress: number;
  consumesPNETPorts: number; // New: PNET Ports
  description?: string; // Optional description for AI context
}

export interface ProjectInputs {
  projectName: string;
  integratorName: string;
  counts: Record<DeviceType, number>;
}

export interface BomItem {
  sku: string;
  name: string;
  description: string;
  quantity: number;
  category: 'Controller' | 'Lighting' | 'Shading' | 'Climate' | 'Accessory' | 'User Interface' | 'Sensors';
  reasoning?: string;
}

export interface PowerStats {
  busLPower: {
    consumed: number;
    supplied: number;
  };
  nPower: {
    consumed: number;
    supplied: number;
  };
}

export interface CategoryCounts {
  lighting: number;
  shading: number;
  climate: number;
  keypads: number;
  sensors: number;
}

export interface SpecificationResult {
  items: BomItem[];
  totalDevices: number;
  summary: string;
  powerStats: PowerStats;
  addressStats: {
    consumed: number;
    supplied: number;
  };
  pnetStats: {
    consumed: number;
    supplied: number;
  };
  categoryCounts: CategoryCounts;
}

export const DEVICE_LABELS: Record<DeviceType, string> = {
  [DeviceType.LIGHT_ONOFF]: 'On/Off Circuits',
  [DeviceType.LIGHT_DIMMER]: 'Dimmer Circuits',
  [DeviceType.LIGHT_PWM]: 'PWM (LED Strip) Circuits',
  [DeviceType.LIGHT_DALI]: 'DALI Addresses/Groups',
  [DeviceType.SHADE_WIRED]: 'Wired Shades',
  [DeviceType.SHADE_WIRELESS]: 'Wireless Shades',
  [DeviceType.CLIMATE_IR]: 'Infrared Control (Split)',
  [DeviceType.CLIMATE_VRV]: 'VRV/VRF Control (Gateway)',
  [DeviceType.KEYPAD_QUANTICA_K]: 'Quantica K Keypads',
  [DeviceType.KEYPAD_QUANTICA_L]: 'Quantica L Keypads',
  [DeviceType.KEYPAD_QUANTICA_P]: 'Quantica P Keypads',
  [DeviceType.KEYPAD_ION]: 'ION Keypads',
  [DeviceType.SENSOR_WIDELUX]: 'Widelux (Occ/Lux)',
  [DeviceType.SENSOR_XRAY]: 'X-Ray (Temp/Air)',
};

