}

const CATEGORIES: ProductCategory[] = ['Processor', 'Lighting Control', 'Shades Control', 'HVAC Control', 'Power Supply', 'Keypad', 'Sensor', 'Accessory'];

const getTypesForCategory = (cat: ProductCategory): string[] => {
  switch (cat) {
    case 'Processor': return ['Processor'];
    case 'Lighting Control': return ['On/Off', 'Dimmer', 'PWM', 'DALI'];
    case 'Shades Control': return ['Wired', 'Wireless'];
    case 'HVAC Control': return ['Infrared', 'VRV/VRF'];
    case 'Power Supply': return ['Bus Power', 'Auxiliary'];
    case 'Keypad': return ['Standard', 'Touch', 'Thermostat', 'Quantica K', 'Quantica L', 'Quantica P', 'ION'];
    case 'Sensor': return ['Motion', 'Presence', 'Lux', 'Temp', 'Widelux', 'X-Ray'];
    case 'Accessory': return ['Power Supply', 'Gateway', 'Repeater', 'Cable', 'Mount'];
    default: return ['Standard'];
  }
