import { ProjectInputs, SpecificationResult, Product, DeviceType, BomItem } from "../types";

export const generateSpecification = async (inputs: ProjectInputs, catalog: Product[]): Promise<SpecificationResult> => {
  // Use let so we can filter/reassign later
  let items: BomItem[] = [];
  const activeCounts = inputs.counts;

  // --- Helper: Generic Optimization Algorithm ---
  const getOptimizedBom = (targetAmount: number, candidates: Product[], getCapacity: (p: Product) => number): Map<Product, number> => {
    const productsByCap = new Map<number, Product>();
    candidates.forEach(p => {
        const cap = getCapacity(p);
        if (cap > 0 && !productsByCap.has(cap)) productsByCap.set(cap, p);
    });

    const capacities = Array.from(productsByCap.keys()).sort((a, b) => b - a);
    if (capacities.length === 0) return new Map();

    const result = new Map<Product, number>();
    if (targetAmount <= 0) return result;

    const maxCap = capacities[0];
    const maxProduct = productsByCap.get(maxCap)!;

    let bulkQty = Math.floor(targetAmount / maxCap);
    // Use slightly fuzzy math for float safety
    let remainder = targetAmount - (bulkQty * maxCap);
    if (remainder < 0.001) remainder = 0;

    if (bulkQty > 0) {
        result.set(maxProduct, bulkQty);
    }

    if (remainder > 0) {
        // Find smallest capacity >= remainder
        const bestFitCap = capacities.filter(cap => cap >= remainder - 0.001).sort((a,b) => a - b)[0];

        if (bestFitCap !== undefined) {
             const p = productsByCap.get(bestFitCap)!;
             result.set(p, (result.get(p) || 0) + 1);
        } else {
             // Fallback: Add another max unit
             const p = maxProduct;
             result.set(p, (result.get(p) || 0) + 1);
        }
    }
    return result;
  };

  // ==========================================
  // STAGE 1: FUNCTIONAL BOM GENERATION
  // ==========================================

  // --- Rule 1: Mandatory Processor ---
  const processors = catalog.filter(p => p.type === 'Processor');
  if (processors.length > 0) {
    const processor = processors[0];
    items.push({
        sku: processor.model,
        name: `${processor.brand} ${processor.type}`,
        description: processor.description || 'System Central Processor',
        quantity: 1,
        category: 'Controller',
        reasoning: 'Mandatory: 1 Main Processor required per system.'
    });
  }

  // --- Configuration: Device Groups & Matching Rules ---
  const INF_GROUPS = [
    // Lighting
    {
      id: 'DIMMER_GROUP',
      types: [DeviceType.LIGHT_DIMMER],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Dimmer'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'RELAY_GROUP',
      types: [DeviceType.LIGHT_ONOFF],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Relay', 'RL', 'On/Off'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'PWM_GROUP',
      types: [DeviceType.LIGHT_PWM],
      targetCategory: 'Lighting Control',
      typeKeywords: ['PWM', 'LED', 'RGB'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'DALI_GROUP',
      types: [DeviceType.LIGHT_DALI],
      targetCategory: 'Lighting Control',
      typeKeywords: ['DALI', 'DL'],
      bomCategory: 'Lighting' as const
    },
    // Shading
    {
      id: 'SHADE_WIRED_GROUP',
      types: [DeviceType.SHADE_WIRED],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wired', 'LX'],
      bomCategory: 'Shading' as const
    },
    {
      id: 'SHADE_WIRELESS_GROUP',
      types: [DeviceType.SHADE_WIRELESS],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wireless', 'GTW'],
      bomCategory: 'Shading' as const
    },
    // Climate
    {
      id: 'HVAC_IR_GROUP',
      types: [DeviceType.CLIMATE_IR],
      targetCategory: 'HVAC Control',
      typeKeywords: ['IR', 'Infrared', 'Emitter', 'SA1'],
      bomCategory: 'Climate' as const
    },
    {
      id: 'HVAC_CENTRAL_GROUP',
      types: [DeviceType.CLIMATE_VRV],
      targetCategory: 'HVAC Control',
      typeKeywords: ['VRV', 'VRF', 'Gateway', 'Thermostat', 'DK'],
      bomCategory: 'Climate' as const
    },
    // Keypads
    {
      id: 'KEYPAD_QK_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_K],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica K'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_QL_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_L],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica L'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_QP_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_P],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica P'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_ION_GROUP',
      types: [DeviceType.KEYPAD_ION],
      targetCategory: 'Keypad',
      typeKeywords: ['ION'],
      bomCategory: 'User Interface' as const
    },
    // Sensors
    {
      id: 'SENSOR_WIDELUX_GROUP',
      types: [DeviceType.SENSOR_WIDELUX],
      targetCategory: 'Sensor',
      typeKeywords: ['Widelux'],
      bomCategory: 'Sensors' as const
    },
    {
      id: 'SENSOR_XRAY_GROUP',
      types: [DeviceType.SENSOR_XRAY],
      targetCategory: 'Sensor',
      typeKeywords: ['X-Ray'],
      bomCategory: 'Sensors' as const
    }
  ];

  // --- Functional Module Calculation ---
  INF_GROUPS.forEach(group => {
    const totalLoad = group.types.reduce((sum, type) => sum + (activeCounts[type] || 0), 0);
    if (totalLoad <= 0) return;

    const candidates = catalog.filter(p => 
      p.category === group.targetCategory && 
      group.typeKeywords.some(k => 
        p.type.toLowerCase().includes(k.toLowerCase()) || 
        p.model.toLowerCase().includes(k.toLowerCase())
      )
    );

    if (candidates.length === 0) {
      items.push({
        sku: 'MISSING-PRODUCT',
        name: `Incompatible: ${group.id}`,
        description: `No catalog products found to control ${totalLoad} devices.`,
        quantity: 0,
        category: 'Accessory',
        reasoning: `Error: Missing ${group.targetCategory} products in Backoffice.`
      });
      return;
    }

    const optimization = getOptimizedBom(totalLoad, candidates, (p) => p.channels);

    optimization.forEach((qty, product) => {
        items.push({
          sku: product.model,
          name: `${product.brand} ${product.type}`,
          description: product.description || `${product.category} (${product.channels} Channels)`,
          quantity: qty,
          category: group.bomCategory,
          reasoning: `Generic Optimization: Total ${totalLoad} loads. ${product.channels}-ch modules selected.`
        });
    });
  });

  // --- Stats Helper ---
  const calculateStats = (currentItems: BomItem[]) => {
    let totals = { 
        consumedL: 0, suppliedL: 0, 
        consumedN: 0, suppliedN: 0,
        consumedAddr: 0, suppliedAddr: 0,
        consumedPNET: 0, suppliedPNET: 0
    };
    currentItems.forEach(item => {
        const p = catalog.find(cp => cp.model === item.sku);
        if (p) {
            totals.consumedL += p.consumesLPower * item.quantity;
            totals.consumedN += p.consumesNPower * item.quantity;
            totals.consumedAddr += p.consumesAddress * item.quantity;
            totals.consumedPNET += p.consumesPNETPorts * item.quantity;

            totals.suppliedL += p.suppliesLPower * item.quantity;
            totals.suppliedN += p.suppliesNPower * item.quantity;
            totals.suppliedAddr += p.suppliesAddress * item.quantity;
            totals.suppliedPNET += p.suppliesPNETPorts * item.quantity;
        }
    });
    return totals;
  };

  // ==========================================
  // STAGE 2: PNET CHECK & UPGRADE
  // ==========================================

  // 1. Calculate Deficit
  let pnetStats = calculateStats(items);
  let deficitPNET = pnetStats.consumedPNET - pnetStats.suppliedPNET;

  // 2a. Upgrade Phase
  // Check if we can swap existing items (that supply 0 ports) for variants that supply ports (e.g., Relay 4ch -> Relay 8ch)
  // This avoids adding "unnecessary" extra modules (Minimize Module Count).
  if (deficitPNET > 0) {
      let changeMade = true;
      while (deficitPNET > 0 && changeMade) {
          changeMade = false;

          let bestCandidate: { index: number, product: Product, score: number } | null = null;

          // Scan ALL items to find the BEST single upgrade candidate
          for (let i = 0; i < items.length; i++) {
              if (deficitPNET <= 0) break;
              const item = items[i];
              if (item.quantity <= 0) continue;

              const p = catalog.find(cp => cp.model === item.sku);
              // Only attempt upgrade if current product supplies 0 ports
              if (!p || p.suppliesPNETPorts > 0) continue; 

              // Find candidates in the same category/type that supply ports and have adequate channels
              const candidates = catalog.filter(up => 
                  up.category.toLowerCase() === p.category.toLowerCase() && 
                  up.type.toLowerCase() === p.type.toLowerCase() && 
                  up.suppliesPNETPorts > 0 && 
                  up.channels >= p.channels
              );

              if (candidates.length === 0) continue;

              // Pick best product for this specific item (prefer highest ports, then lowest channels to minimize waste)
              candidates.sort((a,b) => {
                 if (b.suppliesPNETPorts !== a.suppliesPNETPorts) return b.suppliesPNETPorts - a.suppliesPNETPorts;
                 return a.channels - b.channels;
              });
              const upgradeProduct = candidates[0];

              // Calculate Priority Score
              // Goal: Maximize 'useful' ports gained, break ties with Type preference.
              let score = 0;

              // 1. Utility Score: How much does this upgrade actually help?
              const portsSupplied = upgradeProduct.suppliesPNETPorts;
              const portsUseful = Math.min(portsSupplied, deficitPNET);
              score += portsUseful * 10; 

              // 2. Type Preference (Tie-breakers)
              const typeName = upgradeProduct.type.toLowerCase();
              if (typeName.includes('relay') || typeName.includes('on/off')) score += 5;
              else if (typeName.includes('dimmer')) score += 4;
              else if (typeName.includes('wired') || typeName.includes('shade')) score += 4; // Equal priority to dimmers
              else score += 1;

              if (!bestCandidate || score > bestCandidate.score) {
                  bestCandidate = { index: i, product: upgradeProduct, score };
              }
          }

          // Apply the best upgrade found in this pass
          if (bestCandidate) {
              const item = items[bestCandidate.index];
              const p = catalog.find(cp => cp.model === item.sku)!;

              item.quantity -= 1;
              items.push({
                  sku: bestCandidate.product.model,
                  name: `${bestCandidate.product.brand} ${bestCandidate.product.type}`,
                  description: bestCandidate.product.description || `${bestCandidate.product.category} (${bestCandidate.product.channels} Ch)`,
                  quantity: 1,
                  category: item.category,
                  reasoning: `Upgraded from ${p.model} for PNET connectivity`
              });

              deficitPNET -= bestCandidate.product.suppliesPNETPorts;
              changeMade = true;
          }
      }
  }

  // Filter out items that were reduced to 0 quantity during upgrade
  items = items.filter(i => i.quantity > 0);

  // 2b. Additive Phase (Fallthrough)
  // If upgrading existing items wasn't enough (or no upgradable items existed), add new modules
  if (deficitPNET > 0) {
    // Sort to prioritize Relays (like RL8) over Dimmers (like DIM8)
    const pnetCandidates = catalog
        .filter(p => p.suppliesPNETPorts > 0)
        .sort((a, b) => {
            const aType = a.type.toLowerCase();
            const bType = b.type.toLowerCase();

            // 1. Prefer Relays
            const aIsRelay = aType.includes('relay') || aType.includes('on/off');
            const bIsRelay = bType.includes('relay') || bType.includes('on/off');
            if (aIsRelay && !bIsRelay) return -1;
            if (!aIsRelay && bIsRelay) return 1;

            // 2. Deprioritize Dimmers
            const aIsDimmer = aType.includes('dimmer');
            const bIsDimmer = bType.includes('dimmer');
            if (aIsDimmer && !bIsDimmer) return 1;
            if (!aIsDimmer && bIsDimmer) return -1;

            // 3. Prefer lower channel count (cheaper filler, e.g. RL8 over RL12)
            // Since getOptimizedBom picks the first match for a capacity, sorting ascending channels helps.
            return a.channels - b.channels;
        });

    if (pnetCandidates.length === 0) {
        items.push({
          sku: 'MISSING-PNET-MODULE',
          name: 'PNET Port Deficit',
          description: `System needs ${deficitPNET} PNET ports.`,
          quantity: 1,
          category: 'Accessory',
          reasoning: 'Error: No device found to supply PNET Ports.'
        });
    } else {
        const pnetBom = getOptimizedBom(deficitPNET, pnetCandidates, (p) => p.suppliesPNETPorts);

        pnetBom.forEach((qty, product) => {
            items.push({
                sku: product.model,
                name: `${product.brand} ${product.type}`,
                description: product.description || `PNET Port Expansion (Module)`,
                quantity: qty,
                category: 'Accessory',
                reasoning: `PNET Port Deficit: ${deficitPNET} ports needed. Added extra module (${product.type}) to supply ports.`
            });
        });
    }
  }

  // ==========================================
  // STAGE 3: POWER CHECK
  // ==========================================

  // Resolve NPower (Network Power)
  // Re-calculate stats because upgrades/additions might have changed things
  let stats = calculateStats(items);
  let deficitN = stats.consumedN - stats.suppliedN;

  if (deficitN > 0) {
      const nCandidates = catalog.filter(p => p.suppliesNPower > 0);

      if (nCandidates.length === 0) {
          items.push({
            sku: 'MISSING-N-PWR',
            name: 'Network Power Deficit',
            description: `System needs ${deficitN.toFixed(2)} units of NPower.`,
            quantity: 1,
            category: 'Accessory',
            reasoning: 'Error: No device found to supply Network Power.'
          });
      } else {
          const nBom = getOptimizedBom(deficitN, nCandidates, (p) => p.suppliesNPower);

          nBom.forEach((qty, product) => {
              items.push({
                  sku: product.model,
                  name: `${product.brand} ${product.type}`,
                  description: product.description || `Network Power Supply`,
                  quantity: qty,
                  category: 'Accessory',
                  reasoning: `NPower Deficit: ${deficitN.toFixed(2)}. Added to supply network power.`
              });
          });
      }
  }

  // Rule: Devices requiring dedicated Power Supply
  const devicesNeedingPS = items.filter(item => {
      const p = catalog.find(cp => cp.model === item.sku);
      return p?.requiresDedicatedPS;
  });

  // Calculate total dedicated PS modules needed (1 per unit of device)
  const totalDedPSNeeded = devicesNeedingPS.reduce((sum, item) => sum + item.quantity, 0);

  if (totalDedPSNeeded > 0) {
      const psCandidates = catalog
          .filter(p => p.type === 'Power Supply' && p.suppliesLPower > 0)
          .sort((a, b) => b.suppliesLPower - a.suppliesLPower);

      if (psCandidates.length > 0) {
          const primaryPS = psCandidates[0];
          items.push({
              sku: primaryPS.model,
              name: `${primaryPS.brand} ${primaryPS.type}`,
              description: primaryPS.description || `Dedicated Power Supply`,
              quantity: totalDedPSNeeded,
              category: 'Accessory',
              reasoning: `Rule: Dedicated Power Supply required for specific devices (${totalDedPSNeeded} units needed).`
          });
      } else {
           items.push({
            sku: 'MISSING-PWR-SUPPLY',
            name: 'Power Supply Missing',
            description: `No Power Supply found in catalog for dedicated devices.`,
            quantity: totalDedPSNeeded,
            category: 'Accessory',
            reasoning: 'Error: Devices require Dedicated Power Supply but none found.'
          });
      }
  }

  // Resolve LPower (Logic/Line Power)
  let moduleLoadL = 0;
  let availableGeneralL = 0;

  items.forEach(item => {
    const p = catalog.find(cp => cp.model === item.sku);
    if (!p) return;

    const requiresDedicated = p.requiresDedicatedPS;
    const isDedicatedPS = item.reasoning?.includes('Dedicated Power Supply');

    if (requiresDedicated) {
        // Device has its own dedicated PSU (added above), so its consumption is covered.
        // We do not add its consumption to the general bus load.
    } else if (isDedicatedPS) {
        // This is the dedicated PSU itself.
        // We do not add its supply to the general bus availability.
    } else {
        moduleLoadL += p.consumesLPower * item.quantity;
        availableGeneralL += p.suppliesLPower * item.quantity;
    }
  });

  let deficitL = moduleLoadL - availableGeneralL;

  if (deficitL > 0) {
      const lCandidates = catalog.filter(p => p.suppliesLPower > 0);

      if (lCandidates.length === 0) {
           items.push({
            sku: 'MISSING-L-PWR',
            name: 'Line Power Deficit',
            description: `Modules need ${deficitL.toFixed(2)} units of LPower (excluding processors/dedicated devices).`,
            quantity: 1,
            category: 'Accessory',
            reasoning: 'Error: No device found to supply Line Power.'
          });
      } else {
          const lBom = getOptimizedBom(deficitL, lCandidates, (p) => p.suppliesLPower);

          lBom.forEach((qty, product) => {
              items.push({
                  sku: product.model,
                  name: `${product.brand} ${product.type}`,
                  description: product.description || `Line Power Supply`,
                  quantity: qty,
                  category: 'Accessory',
                  reasoning: `Module LPower Load: ${deficitL.toFixed(2)}. Added to supply bus power.`
              });
              availableGeneralL += product.suppliesLPower * qty;
          });
      }
  }

  // --- Aggregation Step ---
  const aggregatedItemsMap = new Map<string, BomItem>();

  items.forEach(item => {
    if (aggregatedItemsMap.has(item.sku)) {
        const existing = aggregatedItemsMap.get(item.sku)!;
        existing.quantity += item.quantity;
        if (existing.reasoning !== item.reasoning) {
            existing.reasoning = `${existing.reasoning} | ${item.reasoning}`;
        }
    } else {
        aggregatedItemsMap.set(item.sku, { ...item });
    }
  });

  const finalItems = Array.from(aggregatedItemsMap.values());
  const totalDevices = Object.values(activeCounts).reduce((a, b) => a + b, 0);

  // Calculate Category Counts
  const categoryCounts = {
      lighting: (activeCounts[DeviceType.LIGHT_ONOFF] || 0) + 
                (activeCounts[DeviceType.LIGHT_DIMMER] || 0) + 
                (activeCounts[DeviceType.LIGHT_PWM] || 0) + 
                (activeCounts[DeviceType.LIGHT_DALI] || 0),
      shading: (activeCounts[DeviceType.SHADE_WIRED] || 0) + 
               (activeCounts[DeviceType.SHADE_WIRELESS] || 0),
      climate: (activeCounts[DeviceType.CLIMATE_IR] || 0) + 
               (activeCounts[DeviceType.CLIMATE_VRV] || 0),
      keypads: (activeCounts[DeviceType.KEYPAD_QUANTICA_K] || 0) +
               (activeCounts[DeviceType.KEYPAD_QUANTICA_L] || 0) +
               (activeCounts[DeviceType.KEYPAD_QUANTICA_P] || 0) +
               (activeCounts[DeviceType.KEYPAD_ION] || 0),
      sensors: (activeCounts[DeviceType.SENSOR_WIDELUX] || 0) +
               (activeCounts[DeviceType.SENSOR_XRAY] || 0),
  };

  // Final Stats
  const finalStats = calculateStats(finalItems);

  return {
    items: finalItems,
    totalDevices,
    summary: `Specification generated.`,
    powerStats: {
        busLPower: {
            consumed: moduleLoadL,
            supplied: availableGeneralL
        },
        nPower: {
            consumed: finalStats.consumedN,
            supplied: finalStats.suppliedN
        }
    },
    addressStats: {
        consumed: finalStats.consumedAddr,
        supplied: finalStats.suppliedAddr
    },
    pnetStats: {
        consumed: finalStats.consumedPNET,
        supplied: finalStats.suppliedPNET
    },
    categoryCounts
  };
};

import { ProjectInputs, SpecificationResult, Product, DeviceType, BomItem } from "../types";

export const generateSpecification = async (inputs: ProjectInputs, catalog: Product[]): Promise<SpecificationResult> => {
  // Use let so we can filter/reassign later
  let items: BomItem[] = [];
  const activeCounts = inputs.counts;

  // --- Helper: Generic Optimization Algorithm ---
  const getOptimizedBom = (targetAmount: number, candidates: Product[], getCapacity: (p: Product) => number): Map<Product, number> => {
    const productsByCap = new Map<number, Product>();
    candidates.forEach(p => {
        const cap = getCapacity(p);
        if (cap > 0 && !productsByCap.has(cap)) productsByCap.set(cap, p);
    });

    const capacities = Array.from(productsByCap.keys()).sort((a, b) => b - a);
    if (capacities.length === 0) return new Map();

    const result = new Map<Product, number>();
    if (targetAmount <= 0) return result;

    const maxCap = capacities[0];
    const maxProduct = productsByCap.get(maxCap)!;

    let bulkQty = Math.floor(targetAmount / maxCap);
    // Use slightly fuzzy math for float safety
    let remainder = targetAmount - (bulkQty * maxCap);
    if (remainder < 0.001) remainder = 0;

    if (bulkQty > 0) {
        result.set(maxProduct, bulkQty);
    }

    if (remainder > 0) {
        // Find smallest capacity >= remainder
        const bestFitCap = capacities.filter(cap => cap >= remainder - 0.001).sort((a,b) => a - b)[0];

        if (bestFitCap !== undefined) {
             const p = productsByCap.get(bestFitCap)!;
             result.set(p, (result.get(p) || 0) + 1);
        } else {
             // Fallback: Add another max unit
             const p = maxProduct;
             result.set(p, (result.get(p) || 0) + 1);
        }
    }
    return result;
  };

  // ==========================================
  // STAGE 1: FUNCTIONAL BOM GENERATION
  // ==========================================

  // --- Rule 1: Mandatory Processor ---
  const processors = catalog.filter(p => p.type === 'Processor');
  if (processors.length > 0) {
    const processor = processors[0];
    items.push({
        sku: processor.model,
        name: `${processor.brand} ${processor.type}`,
        description: processor.description || 'System Central Processor',
        quantity: 1,
        category: 'Controller',
        reasoning: 'Mandatory: 1 Main Processor required per system.'
    });
  }

  // --- Configuration: Device Groups & Matching Rules ---
  const INF_GROUPS = [
    // Lighting
    {
      id: 'DIMMER_GROUP',
      types: [DeviceType.LIGHT_DIMMER],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Dimmer'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'RELAY_GROUP',
      types: [DeviceType.LIGHT_ONOFF],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Relay', 'RL', 'On/Off'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'PWM_GROUP',
      types: [DeviceType.LIGHT_PWM],
      targetCategory: 'Lighting Control',
      typeKeywords: ['PWM', 'LED', 'RGB'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'DALI_GROUP',
      types: [DeviceType.LIGHT_DALI],
      targetCategory: 'Lighting Control',
      typeKeywords: ['DALI', 'DL'],
      bomCategory: 'Lighting' as const
    },
    // Shading
    {
      id: 'SHADE_WIRED_GROUP',
      types: [DeviceType.SHADE_WIRED],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wired', 'LX'],
      bomCategory: 'Shading' as const
    },
    {
      id: 'SHADE_WIRELESS_GROUP',
      types: [DeviceType.SHADE_WIRELESS],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wireless', 'GTW'],
      bomCategory: 'Shading' as const
    },
    // Climate
    {
      id: 'HVAC_IR_GROUP',
      types: [DeviceType.CLIMATE_IR],
      targetCategory: 'HVAC Control',
      typeKeywords: ['IR', 'Infrared', 'Emitter', 'SA1'],
      bomCategory: 'Climate' as const
    },
    {
      id: 'HVAC_CENTRAL_GROUP',
      types: [DeviceType.CLIMATE_VRV],
      targetCategory: 'HVAC Control',
      typeKeywords: ['VRV', 'VRF', 'Gateway', 'Thermostat', 'DK'],
      bomCategory: 'Climate' as const
    },
    // Keypads
    {
      id: 'KEYPAD_QK_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_K],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica K'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_QL_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_L],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica L'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_QP_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_P],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica P'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_ION_GROUP',
      types: [DeviceType.KEYPAD_ION],
      targetCategory: 'Keypad',
      typeKeywords: ['ION'],
      bomCategory: 'User Interface' as const
    },
    // Sensors
    {
      id: 'SENSOR_WIDELUX_GROUP',
      types: [DeviceType.SENSOR_WIDELUX],
      targetCategory: 'Sensor',
      typeKeywords: ['Widelux'],
      bomCategory: 'Sensors' as const
    },
    {
      id: 'SENSOR_XRAY_GROUP',
      types: [DeviceType.SENSOR_XRAY],
      targetCategory: 'Sensor',
      typeKeywords: ['X-Ray'],
      bomCategory: 'Sensors' as const
    }
  ];

  // --- Functional Module Calculation ---
  INF_GROUPS.forEach(group => {
    const totalLoad = group.types.reduce((sum, type) => sum + (activeCounts[type] || 0), 0);
    if (totalLoad <= 0) return;

    const candidates = catalog.filter(p => 
      p.category === group.targetCategory && 
      group.typeKeywords.some(k => 
        p.type.toLowerCase().includes(k.toLowerCase()) || 
        p.model.toLowerCase().includes(k.toLowerCase())
      )
    );

    if (candidates.length === 0) {
      items.push({
        sku: 'MISSING-PRODUCT',
        name: `Incompatible: ${group.id}`,
        description: `No catalog products found to control ${totalLoad} devices.`,
        quantity: 0,
        category: 'Accessory',
        reasoning: `Error: Missing ${group.targetCategory} products in Backoffice.`
      });
      return;
    }

    const optimization = getOptimizedBom(totalLoad, candidates, (p) => p.channels);

    optimization.forEach((qty, product) => {
        items.push({
          sku: product.model,
          name: `${product.brand} ${product.type}`,
          description: product.description || `${product.category} (${product.channels} Channels)`,
          quantity: qty,
          category: group.bomCategory,
          reasoning: `Generic Optimization: Total ${totalLoad} loads. ${product.channels}-ch modules selected.`
        });
    });
  });

  // --- Stats Helper ---
  const calculateStats = (currentItems: BomItem[]) => {
    let totals = { 
        consumedL: 0, suppliedL: 0, 
        consumedN: 0, suppliedN: 0,
        consumedAddr: 0, suppliedAddr: 0,
        consumedPNET: 0, suppliedPNET: 0
    };
    currentItems.forEach(item => {
        const p = catalog.find(cp => cp.model === item.sku);
        if (p) {
            totals.consumedL += p.consumesLPower * item.quantity;
            totals.consumedN += p.consumesNPower * item.quantity;
            totals.consumedAddr += p.consumesAddress * item.quantity;
            totals.consumedPNET += p.consumesPNETPorts * item.quantity;

            totals.suppliedL += p.suppliesLPower * item.quantity;
            totals.suppliedN += p.suppliesNPower * item.quantity;
            totals.suppliedAddr += p.suppliesAddress * item.quantity;
            totals.suppliedPNET += p.suppliesPNETPorts * item.quantity;
        }
    });
    return totals;
  };

  // ==========================================
  // STAGE 2: PNET CHECK & UPGRADE
  // ==========================================

  // 1. Calculate Deficit
  let pnetStats = calculateStats(items);
  let deficitPNET = pnetStats.consumedPNET - pnetStats.suppliedPNET;

  // 2a. Upgrade Phase
  // Check if we can swap existing items (that supply 0 ports) for variants that supply ports (e.g., Relay 4ch -> Relay 8ch)
  // This avoids adding "unnecessary" extra modules (Minimize Module Count).
  if (deficitPNET > 0) {
      let changeMade = true;
      while (deficitPNET > 0 && changeMade) {
          changeMade = false;

          let bestCandidate: { index: number, product: Product, score: number } | null = null;

          // Scan ALL items to find the BEST single upgrade candidate
          for (let i = 0; i < items.length; i++) {
              if (deficitPNET <= 0) break;
              const item = items[i];
              if (item.quantity <= 0) continue;

              const p = catalog.find(cp => cp.model === item.sku);
              // Only attempt upgrade if current product supplies 0 ports
              if (!p || p.suppliesPNETPorts > 0) continue; 

              // Find candidates in the same category/type that supply ports and have adequate channels
              const candidates = catalog.filter(up => 
                  up.category.toLowerCase() === p.category.toLowerCase() && 
                  up.type.toLowerCase() === p.type.toLowerCase() && 
                  up.suppliesPNETPorts > 0 && 
                  up.channels >= p.channels
              );

              if (candidates.length === 0) continue;

              // Pick best product for this specific item (prefer highest ports, then lowest channels to minimize waste)
              candidates.sort((a,b) => {
                 if (b.suppliesPNETPorts !== a.suppliesPNETPorts) return b.suppliesPNETPorts - a.suppliesPNETPorts;
                 return a.channels - b.channels;
              });
              const upgradeProduct = candidates[0];

              // Calculate Priority Score
              // Goal: Maximize 'useful' ports gained, break ties with Type preference.
              let score = 0;

              // 1. Utility Score: How much does this upgrade actually help?
              const portsSupplied = upgradeProduct.suppliesPNETPorts;
              const portsUseful = Math.min(portsSupplied, deficitPNET);
              score += portsUseful * 10; 

              // 2. Type Preference (Tie-breakers)
              const typeName = upgradeProduct.type.toLowerCase();
              if (typeName.includes('relay') || typeName.includes('on/off')) score += 5;
              else if (typeName.includes('dimmer')) score += 4;
              else if (typeName.includes('wired') || typeName.includes('shade')) score += 4; // Equal priority to dimmers
              else score += 1;

              if (!bestCandidate || score > bestCandidate.score) {
                  bestCandidate = { index: i, product: upgradeProduct, score };
              }
          }

          // Apply the best upgrade found in this pass
          if (bestCandidate) {
              const item = items[bestCandidate.index];
              const p = catalog.find(cp => cp.model === item.sku)!;

              item.quantity -= 1;
              items.push({
                  sku: bestCandidate.product.model,
                  name: `${bestCandidate.product.brand} ${bestCandidate.product.type}`,
                  description: bestCandidate.product.description || `${bestCandidate.product.category} (${bestCandidate.product.channels} Ch)`,
                  quantity: 1,
                  category: item.category,
                  reasoning: `Upgraded from ${p.model} for PNET connectivity`
              });

              deficitPNET -= bestCandidate.product.suppliesPNETPorts;
              changeMade = true;
          }
      }
  }

  // Filter out items that were reduced to 0 quantity during upgrade
  items = items.filter(i => i.quantity > 0);

  // 2b. Additive Phase (Fallthrough)
  // If upgrading existing items wasn't enough (or no upgradable items existed), add new modules
  if (deficitPNET > 0) {
    // Sort to prioritize Relays (like RL8) over Dimmers (like DIM8)
    const pnetCandidates = catalog
        .filter(p => p.suppliesPNETPorts > 0)
        .sort((a, b) => {
            const aType = a.type.toLowerCase();
            const bType = b.type.toLowerCase();

            // 1. Prefer Relays
            const aIsRelay = aType.includes('relay') || aType.includes('on/off');
            const bIsRelay = bType.includes('relay') || bType.includes('on/off');
            if (aIsRelay && !bIsRelay) return -1;
            if (!aIsRelay && bIsRelay) return 1;

            // 2. Deprioritize Dimmers
            const aIsDimmer = aType.includes('dimmer');
            const bIsDimmer = bType.includes('dimmer');
            if (aIsDimmer && !bIsDimmer) return 1;
            if (!aIsDimmer && bIsDimmer) return -1;

            // 3. Prefer lower channel count (cheaper filler, e.g. RL8 over RL12)
            // Since getOptimizedBom picks the first match for a capacity, sorting ascending channels helps.
            return a.channels - b.channels;
        });

    if (pnetCandidates.length === 0) {
        items.push({
          sku: 'MISSING-PNET-MODULE',
          name: 'PNET Port Deficit',
          description: `System needs ${deficitPNET} PNET ports.`,
          quantity: 1,
          category: 'Accessory',
          reasoning: 'Error: No device found to supply PNET Ports.'
        });
    } else {
        const pnetBom = getOptimizedBom(deficitPNET, pnetCandidates, (p) => p.suppliesPNETPorts);

        pnetBom.forEach((qty, product) => {
            items.push({
                sku: product.model,
                name: `${product.brand} ${product.type}`,
                description: product.description || `PNET Port Expansion (Module)`,
                quantity: qty,
                category: 'Accessory',
                reasoning: `PNET Port Deficit: ${deficitPNET} ports needed. Added extra module (${product.type}) to supply ports.`
            });
        });
    }
  }

  // ==========================================
  // STAGE 3: POWER CHECK
  // ==========================================

  // Resolve NPower (Network Power)
  // Re-calculate stats because upgrades/additions might have changed things
  let stats = calculateStats(items);
  let deficitN = stats.consumedN - stats.suppliedN;

  if (deficitN > 0) {
      // Exclude Processors from candidates for expansion power to prefer Hubs (like RDP-HUB6)
      const nCandidates = catalog.filter(p => p.suppliesNPower > 0 && p.type !== 'Processor');

      if (nCandidates.length === 0) {
          items.push({
            sku: 'MISSING-N-PWR',
            name: 'Network Power Deficit',
            description: `System needs ${deficitN.toFixed(2)} units of NPower.`,
            quantity: 1,
            category: 'Accessory',
            reasoning: 'Error: No device found to supply Network Power (checked for non-processor devices).'
          });
      } else {
          const nBom = getOptimizedBom(deficitN, nCandidates, (p) => p.suppliesNPower);

          nBom.forEach((qty, product) => {
              items.push({
                  sku: product.model,
                  name: `${product.brand} ${product.type}`,
                  description: product.description || `Network Power Supply`,
                  quantity: qty,
                  category: 'Accessory',
                  reasoning: `NPower Deficit: ${deficitN.toFixed(2)}. Added to supply network power.`
              });
          });
      }
  }

  // Rule: Devices requiring dedicated Power Supply
  const devicesNeedingPS = items.filter(item => {
      const p = catalog.find(cp => cp.model === item.sku);
      return p?.requiresDedicatedPS;
  });

  // Calculate total dedicated PS modules needed (1 per unit of device)
  const totalDedPSNeeded = devicesNeedingPS.reduce((sum, item) => sum + item.quantity, 0);

  if (totalDedPSNeeded > 0) {
      const psCandidates = catalog
          .filter(p => p.type === 'Power Supply' && p.suppliesLPower > 0)
          .sort((a, b) => b.suppliesLPower - a.suppliesLPower);

      if (psCandidates.length > 0) {
          const primaryPS = psCandidates[0];
          items.push({
              sku: primaryPS.model,
              name: `${primaryPS.brand} ${primaryPS.type}`,
              description: primaryPS.description || `Dedicated Power Supply`,
              quantity: totalDedPSNeeded,
              category: 'Accessory',
              reasoning: `Rule: Dedicated Power Supply required for specific devices (${totalDedPSNeeded} units needed).`
          });
      } else {
           items.push({
            sku: 'MISSING-PWR-SUPPLY',
            name: 'Power Supply Missing',
            description: `No Power Supply found in catalog for dedicated devices.`,
            quantity: totalDedPSNeeded,
            category: 'Accessory',
            reasoning: 'Error: Devices require Dedicated Power Supply but none found.'
          });
      }
  }

  // Resolve LPower (Logic/Line Power)
  let moduleLoadL = 0;
  let availableGeneralL = 0;

  items.forEach(item => {
    const p = catalog.find(cp => cp.model === item.sku);
    if (!p) return;

    const requiresDedicated = p.requiresDedicatedPS;
    const isDedicatedPS = item.reasoning?.includes('Dedicated Power Supply');

    if (requiresDedicated) {
        // Device has its own dedicated PSU (added above), so its consumption is covered.
        // We do not add its consumption to the general bus load.
    } else if (isDedicatedPS) {
        // This is the dedicated PSU itself.
        // We do not add its supply to the general bus availability.
    } else {
        moduleLoadL += p.consumesLPower * item.quantity;
        availableGeneralL += p.suppliesLPower * item.quantity;
    }
  });

  let deficitL = moduleLoadL - availableGeneralL;

  if (deficitL > 0) {
      const lCandidates = catalog.filter(p => p.suppliesLPower > 0);

      if (lCandidates.length === 0) {
           items.push({
            sku: 'MISSING-L-PWR',
            name: 'Line Power Deficit',
            description: `Modules need ${deficitL.toFixed(2)} units of LPower (excluding processors/dedicated devices).`,
            quantity: 1,
            category: 'Accessory',
            reasoning: 'Error: No device found to supply Line Power.'
          });
      } else {
          const lBom = getOptimizedBom(deficitL, lCandidates, (p) => p.suppliesLPower);

          lBom.forEach((qty, product) => {
              items.push({
                  sku: product.model,
                  name: `${product.brand} ${product.type}`,
                  description: product.description || `Line Power Supply`,
                  quantity: qty,
                  category: 'Accessory',
                  reasoning: `Module LPower Load: ${deficitL.toFixed(2)}. Added to supply bus power.`
              });
              availableGeneralL += product.suppliesLPower * qty;
          });
      }
  }

  // --- Aggregation Step ---
  const aggregatedItemsMap = new Map<string, BomItem>();

  items.forEach(item => {
    if (aggregatedItemsMap.has(item.sku)) {
        const existing = aggregatedItemsMap.get(item.sku)!;
        existing.quantity += item.quantity;
        if (existing.reasoning !== item.reasoning) {
            existing.reasoning = `${existing.reasoning} | ${item.reasoning}`;
        }
    } else {
        aggregatedItemsMap.set(item.sku, { ...item });
    }
  });

  const finalItems = Array.from(aggregatedItemsMap.values());
  const totalDevices = Object.values(activeCounts).reduce((a, b) => a + b, 0);

  // Calculate Category Counts
  const categoryCounts = {
      lighting: (activeCounts[DeviceType.LIGHT_ONOFF] || 0) + 
                (activeCounts[DeviceType.LIGHT_DIMMER] || 0) + 
                (activeCounts[DeviceType.LIGHT_PWM] || 0) + 
                (activeCounts[DeviceType.LIGHT_DALI] || 0),
      shading: (activeCounts[DeviceType.SHADE_WIRED] || 0) + 
               (activeCounts[DeviceType.SHADE_WIRELESS] || 0),
      climate: (activeCounts[DeviceType.CLIMATE_IR] || 0) + 
               (activeCounts[DeviceType.CLIMATE_VRV] || 0),
      keypads: (activeCounts[DeviceType.KEYPAD_QUANTICA_K] || 0) +
               (activeCounts[DeviceType.KEYPAD_QUANTICA_L] || 0) +
               (activeCounts[DeviceType.KEYPAD_QUANTICA_P] || 0) +
               (activeCounts[DeviceType.KEYPAD_ION] || 0),
      sensors: (activeCounts[DeviceType.SENSOR_WIDELUX] || 0) +
               (activeCounts[DeviceType.SENSOR_XRAY] || 0),
  };

  // Final Stats
  const finalStats = calculateStats(finalItems);

  return {
    items: finalItems,
    totalDevices,
    summary: `Specification generated.`,
    powerStats: {
        busLPower: {
            consumed: moduleLoadL,
            supplied: availableGeneralL
        },
        nPower: {
            consumed: finalStats.consumedN,
            supplied: finalStats.suppliedN
        }
    },
    addressStats: {
        consumed: finalStats.consumedAddr,
        supplied: finalStats.suppliedAddr
    },
    pnetStats: {
        consumed: finalStats.consumedPNET,
        supplied: finalStats.suppliedPNET
    },
    categoryCounts
  };
};

import { ProjectInputs, SpecificationResult, Product, DeviceType, BomItem } from "../types";

export const generateSpecification = async (inputs: ProjectInputs, catalog: Product[]): Promise<SpecificationResult> => {
  // Use let so we can filter/reassign later
  let items: BomItem[] = [];
  const activeCounts = inputs.counts;

  // --- Helper: Generic Optimization Algorithm ---
  const getOptimizedBom = (targetAmount: number, candidates: Product[], getCapacity: (p: Product) => number): Map<Product, number> => {
    const productsByCap = new Map<number, Product>();
    candidates.forEach(p => {
        const cap = getCapacity(p);
        if (cap > 0 && !productsByCap.has(cap)) productsByCap.set(cap, p);
    });

    const capacities = Array.from(productsByCap.keys()).sort((a, b) => b - a);
    if (capacities.length === 0) return new Map();

    const result = new Map<Product, number>();
    if (targetAmount <= 0) return result;

    const maxCap = capacities[0];
    const maxProduct = productsByCap.get(maxCap)!;

    let bulkQty = Math.floor(targetAmount / maxCap);
    // Use slightly fuzzy math for float safety
    let remainder = targetAmount - (bulkQty * maxCap);
    if (remainder < 0.001) remainder = 0;

    if (bulkQty > 0) {
        result.set(maxProduct, bulkQty);
    }

    if (remainder > 0) {
        // Find smallest capacity >= remainder
        const bestFitCap = capacities.filter(cap => cap >= remainder - 0.001).sort((a,b) => a - b)[0];

        if (bestFitCap !== undefined) {
             const p = productsByCap.get(bestFitCap)!;
             result.set(p, (result.get(p) || 0) + 1);
        } else {
             // Fallback: Add another max unit
             const p = maxProduct;
             result.set(p, (result.get(p) || 0) + 1);
        }
    }
    return result;
  };

  // --- Stats Helper ---
  const calculateStats = (currentItems: BomItem[]) => {
    let totals = { 
        consumedL: 0, suppliedL: 0, 
        consumedN: 0, suppliedN: 0,
        consumedAddr: 0, suppliedAddr: 0,
        consumedPNET: 0, suppliedPNET: 0
    };
    currentItems.forEach(item => {
        const p = catalog.find(cp => cp.model === item.sku);
        if (p) {
            totals.consumedL += p.consumesLPower * item.quantity;
            totals.consumedN += p.consumesNPower * item.quantity;
            totals.consumedAddr += p.consumesAddress * item.quantity;
            totals.consumedPNET += p.consumesPNETPorts * item.quantity;

            totals.suppliedL += p.suppliesLPower * item.quantity;
            totals.suppliedN += p.suppliesNPower * item.quantity;
            totals.suppliedAddr += p.suppliesAddress * item.quantity;
            totals.suppliedPNET += p.suppliesPNETPorts * item.quantity;
        }
    });
    return totals;
  };

  // ==========================================
  // STAGE 1: FUNCTIONAL BOM GENERATION
  // ==========================================

  // --- Rule 1: Mandatory Processor ---
  const processors = catalog.filter(p => p.type === 'Processor');
  if (processors.length > 0) {
    const processor = processors[0];
    items.push({
        sku: processor.model,
        name: `${processor.brand} ${processor.type}`,
        description: processor.description || 'System Central Processor',
        quantity: 1,
        category: 'Controller',
        reasoning: 'Mandatory: 1 Main Processor required per system.'
    });
  }

  // --- Configuration: Device Groups & Matching Rules ---
  const INF_GROUPS = [
    // Lighting
    {
      id: 'DIMMER_GROUP',
      types: [DeviceType.LIGHT_DIMMER],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Dimmer'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'RELAY_GROUP',
      types: [DeviceType.LIGHT_ONOFF],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Relay', 'RL', 'On/Off'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'PWM_GROUP',
      types: [DeviceType.LIGHT_PWM],
      targetCategory: 'Lighting Control',
      typeKeywords: ['PWM', 'LED', 'RGB'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'DALI_GROUP',
      types: [DeviceType.LIGHT_DALI],
      targetCategory: 'Lighting Control',
      typeKeywords: ['DALI', 'DL'],
      bomCategory: 'Lighting' as const
    },
    // Shading
    {
      id: 'SHADE_WIRED_GROUP',
      types: [DeviceType.SHADE_WIRED],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wired', 'LX'],
      bomCategory: 'Shading' as const
    },
    {
      id: 'SHADE_WIRELESS_GROUP',
      types: [DeviceType.SHADE_WIRELESS],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wireless', 'GTW'],
      bomCategory: 'Shading' as const
    },
    // Climate
    {
      id: 'HVAC_IR_GROUP',
      types: [DeviceType.CLIMATE_IR],
      targetCategory: 'HVAC Control',
      typeKeywords: ['IR', 'Infrared', 'Emitter', 'SA1'],
      bomCategory: 'Climate' as const
    },
    {
      id: 'HVAC_CENTRAL_GROUP',
      types: [DeviceType.CLIMATE_VRV],
      targetCategory: 'HVAC Control',
      typeKeywords: ['VRV', 'VRF', 'Gateway', 'Thermostat', 'DK'],
      bomCategory: 'Climate' as const
    },
    // Keypads
    {
      id: 'KEYPAD_QK_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_K],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica K'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_QL_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_L],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica L'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_QP_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_P],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica P'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_ION_GROUP',
      types: [DeviceType.KEYPAD_ION],
      targetCategory: 'Keypad',
      typeKeywords: ['ION'],
      bomCategory: 'User Interface' as const
    },
    // Sensors
    {
      id: 'SENSOR_WIDELUX_GROUP',
      types: [DeviceType.SENSOR_WIDELUX],
      targetCategory: 'Sensor',
      typeKeywords: ['Widelux'],
      bomCategory: 'Sensors' as const
    },
    {
      id: 'SENSOR_XRAY_GROUP',
      types: [DeviceType.SENSOR_XRAY],
      targetCategory: 'Sensor',
      typeKeywords: ['X-Ray'],
      bomCategory: 'Sensors' as const
    }
  ];

  // --- Functional Module Calculation ---
  INF_GROUPS.forEach(group => {
    const totalLoad = group.types.reduce((sum, type) => sum + (activeCounts[type] || 0), 0);
    if (totalLoad <= 0) return;

    const candidates = catalog.filter(p => 
      p.category === group.targetCategory && 
      group.typeKeywords.some(k => 
        p.type.toLowerCase().includes(k.toLowerCase()) || 
        p.model.toLowerCase().includes(k.toLowerCase())
      )
    );

    if (candidates.length === 0) {
      items.push({
        sku: 'MISSING-PRODUCT',
        name: `Incompatible: ${group.id}`,
        description: `No catalog products found to control ${totalLoad} devices.`,
        quantity: 0,
        category: 'Accessory',
        reasoning: `Error: Missing ${group.targetCategory} products in Backoffice.`
      });
      return;
    }

    const optimization = getOptimizedBom(totalLoad, candidates, (p) => p.channels);

    optimization.forEach((qty, product) => {
        items.push({
          sku: product.model,
          name: `${product.brand} ${product.type}`,
          description: product.description || `${product.category} (${product.channels} Channels)`,
          quantity: qty,
          category: group.bomCategory,
          reasoning: `Generic Optimization: Total ${totalLoad} loads. ${product.channels}-ch modules selected.`
        });
    });
  });

  // --- Rule: Address Capacity Scaling ---
  // Calculates total addresses consumed by functional modules and scales the processor count.
  const addressStats = calculateStats(items);
  const totalAddresses = addressStats.consumedAddr;
  // 1 Processor required for every 100 addresses (or fraction thereof)
  const requiredProcessors = Math.max(1, Math.ceil(totalAddresses / 100));

  // Find the processor item to update (assuming it was added in the Mandatory Processor step)
  const processorItem = items.find(item => {
      const p = catalog.find(cp => cp.model === item.sku);
      return p?.type === 'Processor';
  });

  if (processorItem) {
      processorItem.quantity = requiredProcessors;
      processorItem.reasoning = `Mandatory: 1 Processor per 100 addresses. System has ${totalAddresses} addresses.`;
  }

  // ==========================================
  // STAGE 2: PNET CHECK & UPGRADE
  // ==========================================

  // 1. Calculate Deficit
  let pnetStats = calculateStats(items);
  let deficitPNET = pnetStats.consumedPNET - pnetStats.suppliedPNET;

  // 2a. Upgrade Phase
  // Check if we can swap existing items (that supply 0 ports) for variants that supply ports (e.g., Relay 4ch -> Relay 8ch)
  // This avoids adding "unnecessary" extra modules (Minimize Module Count).
  if (deficitPNET > 0) {
      let changeMade = true;
      while (deficitPNET > 0 && changeMade) {
          changeMade = false;

          let bestCandidate: { index: number, product: Product, score: number } | null = null;

          // Scan ALL items to find the BEST single upgrade candidate
          for (let i = 0; i < items.length; i++) {
              if (deficitPNET <= 0) break;
              const item = items[i];
              if (item.quantity <= 0) continue;

              const p = catalog.find(cp => cp.model === item.sku);
              // Only attempt upgrade if current product supplies 0 ports
              if (!p || p.suppliesPNETPorts > 0) continue; 

              // Find candidates in the same category/type that supply ports and have adequate channels
              const candidates = catalog.filter(up => 
                  up.category.toLowerCase() === p.category.toLowerCase() && 
                  up.type.toLowerCase() === p.type.toLowerCase() && 
                  up.suppliesPNETPorts > 0 && 
                  up.channels >= p.channels
              );

              if (candidates.length === 0) continue;

              // Pick best product for this specific item (prefer highest ports, then lowest channels to minimize waste)
              candidates.sort((a,b) => {
                 if (b.suppliesPNETPorts !== a.suppliesPNETPorts) return b.suppliesPNETPorts - a.suppliesPNETPorts;
                 return a.channels - b.channels;
              });
              const upgradeProduct = candidates[0];

              // Calculate Priority Score
              // Goal: Maximize 'useful' ports gained, break ties with Type preference.
              let score = 0;

              // 1. Utility Score: How much does this upgrade actually help?
              const portsSupplied = upgradeProduct.suppliesPNETPorts;
              const portsUseful = Math.min(portsSupplied, deficitPNET);
              score += portsUseful * 10; 

              // 2. Type Preference (Tie-breakers)
              const typeName = upgradeProduct.type.toLowerCase();
              if (typeName.includes('relay') || typeName.includes('on/off')) score += 5;
              else if (typeName.includes('dimmer')) score += 4;
              else if (typeName.includes('wired') || typeName.includes('shade')) score += 4; // Equal priority to dimmers
              else score += 1;

              if (!bestCandidate || score > bestCandidate.score) {
                  bestCandidate = { index: i, product: upgradeProduct, score };
              }
          }

          // Apply the best upgrade found in this pass
          if (bestCandidate) {
              const item = items[bestCandidate.index];
              const p = catalog.find(cp => cp.model === item.sku)!;

              item.quantity -= 1;
              items.push({
                  sku: bestCandidate.product.model,
                  name: `${bestCandidate.product.brand} ${bestCandidate.product.type}`,
                  description: bestCandidate.product.description || `${bestCandidate.product.category} (${bestCandidate.product.channels} Ch)`,
                  quantity: 1,
                  category: item.category,
                  reasoning: `Upgraded from ${p.model} for PNET connectivity`
              });

              deficitPNET -= bestCandidate.product.suppliesPNETPorts;
              changeMade = true;
          }
      }
  }

  // Filter out items that were reduced to 0 quantity during upgrade
  items = items.filter(i => i.quantity > 0);

  // 2b. Additive Phase (Fallthrough)
  // If upgrading existing items wasn't enough (or no upgradable items existed), add new modules
  if (deficitPNET > 0) {
    // Sort to prioritize Relays (like RL8) over Dimmers (like DIM8)
    const pnetCandidates = catalog
        .filter(p => p.suppliesPNETPorts > 0)
        .sort((a, b) => {
            const aType = a.type.toLowerCase();
            const bType = b.type.toLowerCase();

            // 1. Prefer Relays
            const aIsRelay = aType.includes('relay') || aType.includes('on/off');
            const bIsRelay = bType.includes('relay') || bType.includes('on/off');
            if (aIsRelay && !bIsRelay) return -1;
            if (!aIsRelay && bIsRelay) return 1;

            // 2. Deprioritize Dimmers
            const aIsDimmer = aType.includes('dimmer');
            const bIsDimmer = bType.includes('dimmer');
            if (aIsDimmer && !bIsDimmer) return 1;
            if (!aIsDimmer && bIsDimmer) return -1;

            // 3. Prefer lower channel count (cheaper filler, e.g. RL8 over RL12)
            // Since getOptimizedBom picks the first match for a capacity, sorting ascending channels helps.
            return a.channels - b.channels;
        });

    if (pnetCandidates.length === 0) {
        items.push({
          sku: 'MISSING-PNET-MODULE',
          name: 'PNET Port Deficit',
          description: `System needs ${deficitPNET} PNET ports.`,
          quantity: 1,
          category: 'Accessory',
          reasoning: 'Error: No device found to supply PNET Ports.'
        });
    } else {
        const pnetBom = getOptimizedBom(deficitPNET, pnetCandidates, (p) => p.suppliesPNETPorts);

        pnetBom.forEach((qty, product) => {
            items.push({
                sku: product.model,
                name: `${product.brand} ${product.type}`,
                description: product.description || `PNET Port Expansion (Module)`,
                quantity: qty,
                category: 'Accessory',
                reasoning: `PNET Port Deficit: ${deficitPNET} ports needed. Added extra module (${product.type}) to supply ports.`
            });
        });
    }
  }

  // ==========================================
  // STAGE 3: POWER CHECK
  // ==========================================

  // Resolve NPower (Network Power)
  // Re-calculate stats because upgrades/additions might have changed things
  let stats = calculateStats(items);
  let deficitN = stats.consumedN - stats.suppliedN;

  if (deficitN > 0) {
      // Exclude Processors from candidates for expansion power to prefer Hubs (like RDP-HUB6)
      const nCandidates = catalog.filter(p => p.suppliesNPower > 0 && p.type !== 'Processor');

      if (nCandidates.length === 0) {
          items.push({
            sku: 'MISSING-N-PWR',
            name: 'Network Power Deficit',
            description: `System needs ${deficitN.toFixed(2)} units of NPower.`,
            quantity: 1,
            category: 'Accessory',
            reasoning: 'Error: No device found to supply Network Power (checked for non-processor devices).'
          });
      } else {
          const nBom = getOptimizedBom(deficitN, nCandidates, (p) => p.suppliesNPower);

          nBom.forEach((qty, product) => {
              items.push({
                  sku: product.model,
                  name: `${product.brand} ${product.type}`,
                  description: product.description || `Network Power Supply`,
                  quantity: qty,
                  category: 'Accessory',
                  reasoning: `NPower Deficit: ${deficitN.toFixed(2)}. Added to supply network power.`
              });
          });
      }
  }

  // Rule: Devices requiring dedicated Power Supply
  const devicesNeedingPS = items.filter(item => {
      const p = catalog.find(cp => cp.model === item.sku);
      return p?.requiresDedicatedPS;
  });

  // Calculate total dedicated PS modules needed (1 per unit of device)
  const totalDedPSNeeded = devicesNeedingPS.reduce((sum, item) => sum + item.quantity, 0);

  if (totalDedPSNeeded > 0) {
      const psCandidates = catalog
          .filter(p => p.type === 'Power Supply' && p.suppliesLPower > 0)
          .sort((a, b) => b.suppliesLPower - a.suppliesLPower);

      if (psCandidates.length > 0) {
          const primaryPS = psCandidates[0];
          items.push({
              sku: primaryPS.model,
              name: `${primaryPS.brand} ${primaryPS.type}`,
              description: primaryPS.description || `Dedicated Power Supply`,
              quantity: totalDedPSNeeded,
              category: 'Accessory',
              reasoning: `Rule: Dedicated Power Supply required for specific devices (${totalDedPSNeeded} units needed).`
          });
      } else {
           items.push({
            sku: 'MISSING-PWR-SUPPLY',
            name: 'Power Supply Missing',
            description: `No Power Supply found in catalog for dedicated devices.`,
            quantity: totalDedPSNeeded,
            category: 'Accessory',
            reasoning: 'Error: Devices require Dedicated Power Supply but none found.'
          });
      }
  }

  // Resolve LPower (Logic/Line Power)
  let moduleLoadL = 0;
  let availableGeneralL = 0;

  items.forEach(item => {
    const p = catalog.find(cp => cp.model === item.sku);
    if (!p) return;

    const requiresDedicated = p.requiresDedicatedPS;
    const isDedicatedPS = item.reasoning?.includes('Dedicated Power Supply');

    if (requiresDedicated) {
        // Device has its own dedicated PSU (added above), so its consumption is covered.
        // We do not add its consumption to the general bus load.
    } else if (isDedicatedPS) {
        // This is the dedicated PSU itself.
        // We do not add its supply to the general bus availability.
    } else {
        moduleLoadL += p.consumesLPower * item.quantity;
        availableGeneralL += p.suppliesLPower * item.quantity;
    }
  });

  let deficitL = moduleLoadL - availableGeneralL;

  if (deficitL > 0) {
      const lCandidates = catalog.filter(p => p.suppliesLPower > 0);

      if (lCandidates.length === 0) {
           items.push({
            sku: 'MISSING-L-PWR',
            name: 'Line Power Deficit',
            description: `Modules need ${deficitL.toFixed(2)} units of LPower (excluding processors/dedicated devices).`,
            quantity: 1,
            category: 'Accessory',
            reasoning: 'Error: No device found to supply Line Power.'
          });
      } else {
          const lBom = getOptimizedBom(deficitL, lCandidates, (p) => p.suppliesLPower);

          lBom.forEach((qty, product) => {
              items.push({
                  sku: product.model,
                  name: `${product.brand} ${product.type}`,
                  description: product.description || `Line Power Supply`,
                  quantity: qty,
                  category: 'Accessory',
                  reasoning: `Module LPower Load: ${deficitL.toFixed(2)}. Added to supply bus power.`
              });
              availableGeneralL += product.suppliesLPower * qty;
          });
      }
  }

  // --- Aggregation Step ---
  const aggregatedItemsMap = new Map<string, BomItem>();

  items.forEach(item => {
    if (aggregatedItemsMap.has(item.sku)) {
        const existing = aggregatedItemsMap.get(item.sku)!;
        existing.quantity += item.quantity;
        if (existing.reasoning !== item.reasoning) {
            existing.reasoning = `${existing.reasoning} | ${item.reasoning}`;
        }
    } else {
        aggregatedItemsMap.set(item.sku, { ...item });
    }
  });

  const finalItems = Array.from(aggregatedItemsMap.values());
  const totalDevices = Object.values(activeCounts).reduce((a, b) => a + b, 0);

  // Calculate Category Counts
  const categoryCounts = {
      lighting: (activeCounts[DeviceType.LIGHT_ONOFF] || 0) + 
                (activeCounts[DeviceType.LIGHT_DIMMER] || 0) + 
                (activeCounts[DeviceType.LIGHT_PWM] || 0) + 
                (activeCounts[DeviceType.LIGHT_DALI] || 0),
      shading: (activeCounts[DeviceType.SHADE_WIRED] || 0) + 
               (activeCounts[DeviceType.SHADE_WIRELESS] || 0),
      climate: (activeCounts[DeviceType.CLIMATE_IR] || 0) + 
               (activeCounts[DeviceType.CLIMATE_VRV] || 0),
      keypads: (activeCounts[DeviceType.KEYPAD_QUANTICA_K] || 0) +
               (activeCounts[DeviceType.KEYPAD_QUANTICA_L] || 0) +
               (activeCounts[DeviceType.KEYPAD_QUANTICA_P] || 0) +
               (activeCounts[DeviceType.KEYPAD_ION] || 0),
      sensors: (activeCounts[DeviceType.SENSOR_WIDELUX] || 0) +
               (activeCounts[DeviceType.SENSOR_XRAY] || 0),
  };

  // Final Stats
  const finalStats = calculateStats(finalItems);

  return {
    items: finalItems,
    totalDevices,
    summary: `Specification generated.`,
    powerStats: {
        busLPower: {
            consumed: moduleLoadL,
            supplied: availableGeneralL
        },
        nPower: {
            consumed: finalStats.consumedN,
            supplied: finalStats.suppliedN
        }
    },
    addressStats: {
        consumed: finalStats.consumedAddr,
        supplied: finalStats.suppliedAddr
    },
    pnetStats: {
        consumed: finalStats.consumedPNET,
        supplied: finalStats.suppliedPNET
    },
    categoryCounts
  };
};

{
  "name": "ROEHN Flux",
  "description": "Um assistente de especificação inteligente para integradores de automação residencial. Gera Listas de Materiais (BOM) precisas a partir dos requisitos do projeto usando IA Gemini.",
  "requestFramePermissions": []
}

export enum DeviceType {
  // Lighting
  LIGHT_ONOFF = 'LIGHT_ONOFF',
  LIGHT_DIMMER = 'LIGHT_DIMMER',
  LIGHT_PWM = 'LIGHT_PWM',
  LIGHT_DALI = 'LIGHT_DALI',
  // Shades
  SHADE_WIRED = 'SHADE_WIRED',
  SHADE_WIRELESS = 'SHADE_WIRELESS',
  // Climate
  CLIMATE_IR = 'CLIMATE_IR',
  CLIMATE_VRV = 'CLIMATE_VRV',
  // Keypads / User Interfaces
  KEYPAD_QUANTICA_K = 'KEYPAD_QUANTICA_K',
  KEYPAD_QUANTICA_L = 'KEYPAD_QUANTICA_L',
  KEYPAD_QUANTICA_P = 'KEYPAD_QUANTICA_P',
  KEYPAD_ION = 'KEYPAD_ION',
  // Sensors
  SENSOR_WIDELUX = 'SENSOR_WIDELUX',
  SENSOR_XRAY = 'SENSOR_XRAY',
}

export type ProductCategory = 'Processor' | 'Lighting Control' | 'Shades Control' | 'HVAC Control' | 'Power Supply' | 'Keypad' | 'Sensor' | 'Accessory';

export interface Product {
  id: number;
  category: ProductCategory;
  type: string;
  brand: string;
  model: string;
  channels: number; // Capacity
  suppliesLPower: number; // Renamed from suppliesPower
  suppliesNPower: number; // New: Network Power
  suppliesAddress: number;
  suppliesPNETPorts: number; // New: PNET Ports
  consumesLPower: number; // Renamed from consumesPower
  consumesNPower: number; // New: Network Power
  consumesAddress: number;
  consumesPNETPorts: number; // New: PNET Ports
  description?: string; // Optional description for AI context
  requiresDedicatedPS?: boolean; // New: Requires exclusive power supply
}

export interface ProjectInputs {
  projectName: string;
  integratorName: string;
  counts: Record<DeviceType, number>;
}

export interface BomItem {
  sku: string;
  name: string;
  description: string;
  quantity: number;
  category: 'Controller' | 'Lighting' | 'Shading' | 'Climate' | 'Accessory' | 'User Interface' | 'Sensors';
  reasoning?: string;
}

export interface PowerStats {
  busLPower: {
    consumed: number;
    supplied: number;
  };
  nPower: {
    consumed: number;
    supplied: number;
  };
}

export interface CategoryCounts {
  lighting: number;
  shading: number;
  climate: number;
  keypads: number;
  sensors: number;
}

export interface SpecificationResult {
  items: BomItem[];
  totalDevices: number;
  summary: string;
  powerStats: PowerStats;
  addressStats: {
    consumed: number;
    supplied: number;
  };
  pnetStats: {
    consumed: number;
    supplied: number;
  };
  categoryCounts: CategoryCounts;
}

export const DEVICE_LABELS: Record<DeviceType, string> = {
  [DeviceType.LIGHT_ONOFF]: 'Circuitos On/Off',
  [DeviceType.LIGHT_DIMMER]: 'Circuitos Dimerizáveis',
  [DeviceType.LIGHT_PWM]: 'Circuitos PWM',
  [DeviceType.LIGHT_DALI]: 'Drivers DALI',
  [DeviceType.SHADE_WIRED]: 'Persianas Cabeadas',
  [DeviceType.SHADE_WIRELESS]: 'Persianas Sem Fio',
  [DeviceType.CLIMATE_IR]: 'Controle Infravermelho',
  [DeviceType.CLIMATE_VRV]: 'Controle VRV/VRF',
  [DeviceType.KEYPAD_QUANTICA_K]: 'Teclados Quantica K',
  [DeviceType.KEYPAD_QUANTICA_L]: 'Teclados Quantica L',
  [DeviceType.KEYPAD_QUANTICA_P]: 'Teclados Quantica P',
  [DeviceType.KEYPAD_ION]: 'Teclados ION',
  [DeviceType.SENSOR_WIDELUX]: 'Sensor de Luminosidade Widelux',
  [DeviceType.SENSOR_XRAY]: 'Sensor de Temp. e Ar X-Ray',
};

import { ProjectInputs, SpecificationResult, Product, DeviceType, BomItem } from "../types";

export const generateSpecification = async (inputs: ProjectInputs, catalog: Product[]): Promise<SpecificationResult> => {
  // Use let so we can filter/reassign later
  let items: BomItem[] = [];
  const activeCounts = inputs.counts;

  // --- Helper: Generic Optimization Algorithm ---
  const getOptimizedBom = (targetAmount: number, candidates: Product[], getCapacity: (p: Product) => number): Map<Product, number> => {
    const productsByCap = new Map<number, Product>();
    candidates.forEach(p => {
        const cap = getCapacity(p);
        if (cap > 0 && !productsByCap.has(cap)) productsByCap.set(cap, p);
    });

    const capacities = Array.from(productsByCap.keys()).sort((a, b) => b - a);
    if (capacities.length === 0) return new Map();

    const result = new Map<Product, number>();
    if (targetAmount <= 0) return result;

    const maxCap = capacities[0];
    const maxProduct = productsByCap.get(maxCap)!;

    let bulkQty = Math.floor(targetAmount / maxCap);
    // Use slightly fuzzy math for float safety
    let remainder = targetAmount - (bulkQty * maxCap);
    if (remainder < 0.001) remainder = 0;

    if (bulkQty > 0) {
        result.set(maxProduct, bulkQty);
    }

    if (remainder > 0) {
        // Find smallest capacity >= remainder
        const bestFitCap = capacities.filter(cap => cap >= remainder - 0.001).sort((a,b) => a - b)[0];

        if (bestFitCap !== undefined) {
             const p = productsByCap.get(bestFitCap)!;
             result.set(p, (result.get(p) || 0) + 1);
        } else {
             // Fallback: Add another max unit
             const p = maxProduct;
             result.set(p, (result.get(p) || 0) + 1);
        }
    }
    return result;
  };

  // --- Stats Helper ---
  const calculateStats = (currentItems: BomItem[]) => {
    let totals = { 
        consumedL: 0, suppliedL: 0, 
        consumedN: 0, suppliedN: 0,
        consumedAddr: 0, suppliedAddr: 0,
        consumedPNET: 0, suppliedPNET: 0
    };
    currentItems.forEach(item => {
        const p = catalog.find(cp => cp.model === item.sku);
        if (p) {
            totals.consumedL += p.consumesLPower * item.quantity;
            totals.consumedN += p.consumesNPower * item.quantity;
            totals.consumedAddr += p.consumesAddress * item.quantity;
            totals.consumedPNET += p.consumesPNETPorts * item.quantity;

            totals.suppliedL += p.suppliesLPower * item.quantity;
            totals.suppliedN += p.suppliesNPower * item.quantity;
            totals.suppliedAddr += p.suppliesAddress * item.quantity;
            totals.suppliedPNET += p.suppliesPNETPorts * item.quantity;
        }
    });
    return totals;
  };

  // ==========================================
  // STAGE 1: FUNCTIONAL BOM GENERATION
  // ==========================================

  // --- Rule 1: Mandatory Processor ---
  const processors = catalog.filter(p => p.type === 'Processor' || p.type === 'Processador');
  if (processors.length > 0) {
    const processor = processors[0];
    items.push({
        sku: processor.model,
        name: `${processor.brand} ${processor.type}`,
        description: processor.description || 'Processador Central do Sistema',
        quantity: 1,
        category: 'Controller',
        reasoning: 'Obrigatório: 1 Processador Principal necessário por sistema.'
    });
  }

  // --- Configuration: Device Groups & Matching Rules ---
  const INF_GROUPS = [
    // Lighting
    {
      id: 'DIMMER_GROUP',
      types: [DeviceType.LIGHT_DIMMER],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Dimmer', 'Dimer'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'RELAY_GROUP',
      types: [DeviceType.LIGHT_ONOFF],
      targetCategory: 'Lighting Control',
      typeKeywords: ['Relay', 'RL', 'On/Off', 'Relé', 'Rele'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'PWM_GROUP',
      types: [DeviceType.LIGHT_PWM],
      targetCategory: 'Lighting Control',
      typeKeywords: ['PWM', 'LED', 'RGB'],
      bomCategory: 'Lighting' as const
    },
    {
      id: 'DALI_GROUP',
      types: [DeviceType.LIGHT_DALI],
      targetCategory: 'Lighting Control',
      typeKeywords: ['DALI', 'DL'],
      bomCategory: 'Lighting' as const
    },
    // Shading
    {
      id: 'SHADE_WIRED_GROUP',
      types: [DeviceType.SHADE_WIRED],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wired', 'LX', 'Cabeada', 'Motor'],
      bomCategory: 'Shading' as const
    },
    {
      id: 'SHADE_WIRELESS_GROUP',
      types: [DeviceType.SHADE_WIRELESS],
      targetCategory: 'Shades Control',
      typeKeywords: ['Wireless', 'GTW', 'Sem Fio'],
      bomCategory: 'Shading' as const
    },
    // Climate
    {
      id: 'HVAC_IR_GROUP',
      types: [DeviceType.CLIMATE_IR],
      targetCategory: 'HVAC Control',
      typeKeywords: ['IR', 'Infrared', 'Emitter', 'SA1', 'Infravermelho'],
      bomCategory: 'Climate' as const
    },
    {
      id: 'HVAC_CENTRAL_GROUP',
      types: [DeviceType.CLIMATE_VRV],
      targetCategory: 'HVAC Control',
      typeKeywords: ['VRV', 'VRF', 'Gateway', 'Thermostat', 'DK'],
      bomCategory: 'Climate' as const
    },
    // Keypads
    {
      id: 'KEYPAD_QK_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_K],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica K'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_QL_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_L],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica L'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_QP_GROUP',
      types: [DeviceType.KEYPAD_QUANTICA_P],
      targetCategory: 'Keypad',
      typeKeywords: ['Quantica P'],
      bomCategory: 'User Interface' as const
    },
    {
      id: 'KEYPAD_ION_GROUP',
      types: [DeviceType.KEYPAD_ION],
      targetCategory: 'Keypad',
      typeKeywords: ['ION'],
      bomCategory: 'User Interface' as const
    },
    // Sensors
    {
      id: 'SENSOR_WIDELUX_GROUP',
      types: [DeviceType.SENSOR_WIDELUX],
      targetCategory: 'Sensor',
      typeKeywords: ['Widelux'],
      bomCategory: 'Sensors' as const
    },
    {
      id: 'SENSOR_XRAY_GROUP',
      types: [DeviceType.SENSOR_XRAY],
      targetCategory: 'Sensor',
      typeKeywords: ['X-Ray'],
      bomCategory: 'Sensors' as const
    }
  ];

  // --- Functional Module Calculation ---
  INF_GROUPS.forEach(group => {
    const totalLoad = group.types.reduce((sum, type) => sum + (activeCounts[type] || 0), 0);
    if (totalLoad <= 0) return;

    const candidates = catalog.filter(p => 
      p.category === group.targetCategory && 
      group.typeKeywords.some(k => 
        p.type.toLowerCase().includes(k.toLowerCase()) || 
        p.model.toLowerCase().includes(k.toLowerCase())
      )
    );

    if (candidates.length === 0) {
      items.push({
        sku: 'MISSING-PRODUCT',
        name: `Incompatível: ${group.id}`,
        description: `Nenhum produto do catálogo encontrado para controlar ${totalLoad} dispositivos.`,
        quantity: 0,
        category: 'Accessory',
        reasoning: `Erro: Faltam produtos de ${group.targetCategory} no Backoffice.`
      });
      return;
    }

    const optimization = getOptimizedBom(totalLoad, candidates, (p) => p.channels);

    optimization.forEach((qty, product) => {
        items.push({
          sku: product.model,
          name: `${product.brand} ${product.type}`,
          description: product.description || `${product.category} (${product.channels} Canais)`,
          quantity: qty,
          category: group.bomCategory,
          reasoning: `Otimização Genérica: Total de ${totalLoad} cargas. Módulos de ${product.channels} canais selecionados.`
        });
    });
  });

  // --- Rule: Address Capacity Scaling ---
  // Calculates total addresses consumed by functional modules and scales the processor count.
  const addressStats = calculateStats(items);
  const totalAddresses = addressStats.consumedAddr;
  // 1 Processor required for every 100 addresses (or fraction thereof)
  const requiredProcessors = Math.max(1, Math.ceil(totalAddresses / 100));

  // Find the processor item to update (assuming it was added in the Mandatory Processor step)
  const processorItem = items.find(item => {
      const p = catalog.find(cp => cp.model === item.sku);
      return p?.type === 'Processor' || p?.type === 'Processador';
  });

  if (processorItem) {
      processorItem.quantity = requiredProcessors;
      processorItem.reasoning = `Obrigatório: 1 Processador a cada 100 endereços. O sistema possui ${totalAddresses} endereços.`;
  }

  // ==========================================
  // STAGE 2: PNET CHECK & UPGRADE
  // ==========================================

  // 1. Calculate Deficit
  let pnetStats = calculateStats(items);
  let deficitPNET = pnetStats.consumedPNET - pnetStats.suppliedPNET;

  // 2a. Upgrade Phase
  // Check if we can swap existing items (that supply 0 ports) for variants that supply ports (e.g., Relay 4ch -> Relay 8ch)
  // This avoids adding "unnecessary" extra modules (Minimize Module Count).
  if (deficitPNET > 0) {
      let changeMade = true;
      while (deficitPNET > 0 && changeMade) {
          changeMade = false;

          let bestCandidate: { index: number, product: Product, score: number } | null = null;

          // Scan ALL items to find the BEST single upgrade candidate
          for (let i = 0; i < items.length; i++) {
              if (deficitPNET <= 0) break;
              const item = items[i];
              if (item.quantity <= 0) continue;

              const p = catalog.find(cp => cp.model === item.sku);
              // Only attempt upgrade if current product supplies 0 ports
              if (!p || p.suppliesPNETPorts > 0) continue; 

              // Find candidates in the same category/type that supply ports and have adequate channels
              const candidates = catalog.filter(up => 
                  up.category.toLowerCase() === p.category.toLowerCase() && 
                  up.type.toLowerCase() === p.type.toLowerCase() && 
                  up.suppliesPNETPorts > 0 && 
                  up.channels >= p.channels
              );

              if (candidates.length === 0) continue;

              // Pick best product for this specific item (prefer highest ports, then lowest channels to minimize waste)
              candidates.sort((a,b) => {
                 if (b.suppliesPNETPorts !== a.suppliesPNETPorts) return b.suppliesPNETPorts - a.suppliesPNETPorts;
                 return a.channels - b.channels;
              });
              const upgradeProduct = candidates[0];

              // Calculate Priority Score
              // Goal: Maximize 'useful' ports gained, break ties with Type preference.
              let score = 0;

              // 1. Utility Score: How much does this upgrade actually help?
              const portsSupplied = upgradeProduct.suppliesPNETPorts;
              const portsUseful = Math.min(portsSupplied, deficitPNET);
              score += portsUseful * 10; 

              // 2. Type Preference (Tie-breakers)
              const typeName = upgradeProduct.type.toLowerCase();
              if (typeName.includes('relay') || typeName.includes('on/off') || typeName.includes('relé') || typeName.includes('rele')) score += 5;
              else if (typeName.includes('dimmer') || typeName.includes('dimer')) score += 4;
              else if (typeName.includes('wired') || typeName.includes('shade') || typeName.includes('cabeada') || typeName.includes('persiana')) score += 4; // Equal priority to dimmers
              else score += 1;

              if (!bestCandidate || score > bestCandidate.score) {
                  bestCandidate = { index: i, product: upgradeProduct, score };
              }
          }

          // Apply the best upgrade found in this pass
          if (bestCandidate) {
              const item = items[bestCandidate.index];
              const p = catalog.find(cp => cp.model === item.sku)!;

              item.quantity -= 1;
              items.push({
                  sku: bestCandidate.product.model,
                  name: `${bestCandidate.product.brand} ${bestCandidate.product.type}`,
                  description: bestCandidate.product.description || `${bestCandidate.product.category} (${bestCandidate.product.channels} Ch)`,
                  quantity: 1,
                  category: item.category,
                  reasoning: `Atualizado de ${p.model} para conectividade PNET`
              });

              deficitPNET -= bestCandidate.product.suppliesPNETPorts;
              changeMade = true;
          }
      }
  }

  // Filter out items that were reduced to 0 quantity during upgrade
  items = items.filter(i => i.quantity > 0);

  // 2b. Additive Phase (Fallthrough)
  // If upgrading existing items wasn't enough (or no upgradable items existed), add new modules
  if (deficitPNET > 0) {
    // Sort to prioritize Relays (like RL8) over Dimmers (like DIM8)
    const pnetCandidates = catalog
        .filter(p => p.suppliesPNETPorts > 0)
        .sort((a, b) => {
            const aType = a.type.toLowerCase();
            const bType = b.type.toLowerCase();

            // 1. Prefer Relays
            const aIsRelay = aType.includes('relay') || aType.includes('on/off') || aType.includes('relé') || aType.includes('rele');
            const bIsRelay = bType.includes('relay') || bType.includes('on/off') || bType.includes('relé') || bType.includes('rele');
            if (aIsRelay && !bIsRelay) return -1;
            if (!aIsRelay && bIsRelay) return 1;

            // 2. Deprioritize Dimmers
            const aIsDimmer = aType.includes('dimmer') || aType.includes('dimer');
            const bIsDimmer = bType.includes('dimmer') || bType.includes('dimer');
            if (aIsDimmer && !bIsDimmer) return 1;
            if (!aIsDimmer && bIsDimmer) return -1;

            // 3. Prefer lower channel count (cheaper filler, e.g. RL8 over RL12)
            // Since getOptimizedBom picks the first match for a capacity, sorting ascending channels helps.
            return a.channels - b.channels;
        });

    if (pnetCandidates.length === 0) {
        items.push({
          sku: 'MISSING-PNET-MODULE',
          name: 'Déficit de Portas PNET',
          description: `O sistema precisa de ${deficitPNET} portas PNET.`,
          quantity: 1,
          category: 'Accessory',
          reasoning: 'Erro: Nenhum dispositivo encontrado para fornecer portas PNET.'
        });
    } else {
        const pnetBom = getOptimizedBom(deficitPNET, pnetCandidates, (p) => p.suppliesPNETPorts);

        pnetBom.forEach((qty, product) => {
            items.push({
                sku: product.model,
                name: `${product.brand} ${product.type}`,
                description: product.description || `Expansão de Portas PNET (Módulo)`,
                quantity: qty,
                category: 'Accessory',
                reasoning: `Déficit de Portas PNET: ${deficitPNET} portas necessárias. Módulo extra adicionado (${product.type}) para fornecer portas.`
            });
        });
    }
  }

  // ==========================================
  // STAGE 3: POWER CHECK
  // ==========================================

  // Resolve NPower (Network Power)
  // Re-calculate stats because upgrades/additions might have changed things
  let stats = calculateStats(items);
  let deficitN = stats.consumedN - stats.suppliedN;

  if (deficitN > 0) {
      // Exclude Processors from candidates for expansion power to prefer Hubs (like RDP-HUB6)
      const nCandidates = catalog.filter(p => p.suppliesNPower > 0 && !p.type.toLowerCase().includes('process'));

      if (nCandidates.length === 0) {
          items.push({
            sku: 'MISSING-N-PWR',
            name: 'Déficit de Alimentação de Rede (NPower)',
            description: `O sistema precisa de ${deficitN.toFixed(2)} unidades de NPower.`,
            quantity: 1,
            category: 'Accessory',
            reasoning: 'Erro: Nenhum dispositivo encontrado para fornecer NPower (verificado dispositivos não-processadores).'
          });
      } else {
          const nBom = getOptimizedBom(deficitN, nCandidates, (p) => p.suppliesNPower);

          nBom.forEach((qty, product) => {
              items.push({
                  sku: product.model,
                  name: `${product.brand} ${product.type}`,
                  description: product.description || `Fonte de Alimentação de Rede`,
                  quantity: qty,
                  category: 'Accessory',
                  reasoning: `Déficit NPower: ${deficitN.toFixed(2)}. Adicionado para fornecer alimentação de rede.`
              });
          });
      }
  }

  // Rule: Devices requiring dedicated Power Supply
  const devicesNeedingPS = items.filter(item => {
      const p = catalog.find(cp => cp.model === item.sku);
      return p?.requiresDedicatedPS;
  });

  // Calculate total dedicated PS modules needed (1 per unit of device)
  const totalDedPSNeeded = devicesNeedingPS.reduce((sum, item) => sum + item.quantity, 0);

  if (totalDedPSNeeded > 0) {
      const psCandidates = catalog
          .filter(p => (p.type === 'Power Supply' || p.type === 'Fonte de Alimentação') && p.suppliesLPower > 0)
          .sort((a, b) => b.suppliesLPower - a.suppliesLPower);

      if (psCandidates.length > 0) {
          const primaryPS = psCandidates[0];
          items.push({
              sku: primaryPS.model,
              name: `${primaryPS.brand} ${primaryPS.type}`,
              description: primaryPS.description || `Fonte de Alimentação Dedicada`,
              quantity: totalDedPSNeeded,
              category: 'Accessory',
              reasoning: `Regra: Fonte de Alimentação Dedicada necessária para dispositivos específicos (${totalDedPSNeeded} unidades necessárias).`
          });
      } else {
           items.push({
            sku: 'MISSING-PWR-SUPPLY',
            name: 'Fonte de Alimentação Ausente',
            description: `Nenhuma Fonte de Alimentação encontrada no catálogo para dispositivos dedicados.`,
            quantity: totalDedPSNeeded,
            category: 'Accessory',
            reasoning: 'Erro: Dispositivos requerem Fonte Dedicada, mas nenhuma foi encontrada.'
          });
      }
  }

  // Resolve LPower (Logic/Line Power)
  let moduleLoadL = 0;
  let availableGeneralL = 0;

  items.forEach(item => {
    const p = catalog.find(cp => cp.model === item.sku);
    if (!p) return;

    const requiresDedicated = p.requiresDedicatedPS;
    // Check various strings for the reasoning flag
    const isDedicatedPS = item.reasoning?.includes('Dedicated Power Supply') || item.reasoning?.includes('Fonte de Alimentação Dedicada');

    if (requiresDedicated) {
        // Device has its own dedicated PSU (added above), so its consumption is covered.
        // We do not add its consumption to the general bus load.
    } else if (isDedicatedPS) {
        // This is the dedicated PSU itself.
        // We do not add its supply to the general bus availability.
    } else {
        moduleLoadL += p.consumesLPower * item.quantity;
        availableGeneralL += p.suppliesLPower * item.quantity;
    }
  });

  let deficitL = moduleLoadL - availableGeneralL;

  if (deficitL > 0) {
      const lCandidates = catalog.filter(p => p.suppliesLPower > 0);

      if (lCandidates.length === 0) {
           items.push({
            sku: 'MISSING-L-PWR',
            name: 'Déficit de Alimentação de Linha (LPower)',
            description: `Módulos precisam de ${deficitL.toFixed(2)} unidades de LPower (excluindo processadores/dispositivos dedicados).`,
            quantity: 1,
            category: 'Accessory',
            reasoning: 'Erro: Nenhum dispositivo encontrado para fornecer LPower.'
          });
      } else {
          const lBom = getOptimizedBom(deficitL, lCandidates, (p) => p.suppliesLPower);

          lBom.forEach((qty, product) => {
              items.push({
                  sku: product.model,
                  name: `${product.brand} ${product.type}`,
                  description: product.description || `Fonte de Alimentação de Linha`,
                  quantity: qty,
                  category: 'Accessory',
                  reasoning: `Carga LPower dos Módulos: ${deficitL.toFixed(2)}. Adicionado para fornecer alimentação ao barramento.`
              });
              availableGeneralL += product.suppliesLPower * qty;
          });
      }
  }

  // --- Aggregation Step ---
  const aggregatedItemsMap = new Map<string, BomItem>();

  items.forEach(item => {
    if (aggregatedItemsMap.has(item.sku)) {
        const existing = aggregatedItemsMap.get(item.sku)!;
        existing.quantity += item.quantity;
        if (existing.reasoning !== item.reasoning) {
            existing.reasoning = `${existing.reasoning} | ${item.reasoning}`;
        }
    } else {
        aggregatedItemsMap.set(item.sku, { ...item });
    }
  });

  const finalItems = Array.from(aggregatedItemsMap.values());
  const totalDevices = Object.values(activeCounts).reduce((a, b) => a + b, 0);

  // Calculate Category Counts
  const categoryCounts = {
      lighting: (activeCounts[DeviceType.LIGHT_ONOFF] || 0) + 
                (activeCounts[DeviceType.LIGHT_DIMMER] || 0) + 
                (activeCounts[DeviceType.LIGHT_PWM] || 0) + 
                (activeCounts[DeviceType.LIGHT_DALI] || 0),
      shading: (activeCounts[DeviceType.SHADE_WIRED] || 0) + 
               (activeCounts[DeviceType.SHADE_WIRELESS] || 0),
      climate: (activeCounts[DeviceType.CLIMATE_IR] || 0) + 
               (activeCounts[DeviceType.CLIMATE_VRV] || 0),
      keypads: (activeCounts[DeviceType.KEYPAD_QUANTICA_K] || 0) +
               (activeCounts[DeviceType.KEYPAD_QUANTICA_L] || 0) +
               (activeCounts[DeviceType.KEYPAD_QUANTICA_P] || 0) +
               (activeCounts[DeviceType.KEYPAD_ION] || 0),
      sensors: (activeCounts[DeviceType.SENSOR_WIDELUX] || 0) +
               (activeCounts[DeviceType.SENSOR_XRAY] || 0),
  };

  // Final Stats
  const finalStats = calculateStats(finalItems);

  return {
    items: finalItems,
    totalDevices,
    summary: `Especificação gerada.`,
    powerStats: {
        busLPower: {
            consumed: moduleLoadL,
            supplied: availableGeneralL
        },
        nPower: {
            consumed: finalStats.consumedN,
            supplied: finalStats.suppliedN
        }
    },
    addressStats: {
        consumed: finalStats.consumedAddr,
        supplied: finalStats.suppliedAddr
    },
    pnetStats: {
        consumed: finalStats.consumedPNET,
        supplied: finalStats.suppliedPNET
    },
    categoryCounts
  };
};

import React, { useState } from 'react';
