  onUpdateProduct: (product: Product) => void;
  showReasoning: boolean;
  onToggleReasoning: (v: boolean) => void;
}

const CATEGORIES: ProductCategory[] = ['Processor', 'Lighting Control', 'Shades Control', 'HVAC Control', 'Power Supply', 'Keypad', 'Sensor', 'Accessory'];

const getTypesForCategory = (cat: ProductCategory): string[] => {
  switch (cat) {
    case 'Processor': return ['Processador'];
    case 'Lighting Control': return ['On/Off', 'Dimer', 'PWM', 'DALI'];
    case 'Shades Control': return ['Cabeada', 'Sem Fio'];
    case 'HVAC Control': return ['Infravermelho', 'VRV/VRF'];
    case 'Power Supply': return ['Alim. Barramento', 'Auxiliar'];
    case 'Keypad': return ['Padrão', 'Touch', 'Termostato', 'Quantica K', 'Quantica L', 'Quantica P', 'ION'];
    case 'Sensor': return ['Movimento', 'Presença', 'Lux', 'Temp', 'Widelux', 'X-Ray'];
    case 'Accessory': return ['Fonte de Alimentação', 'Gateway', 'Repetidor', 'Cabo', 'Montagem'];
    default: return ['Padrão'];
  }
};

const INPUT_CLASS = "w-full bg-white border border-gray-200 rounded px-2 py-1.5 text-xs text-gray-700 focus:border-brand-500 focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-sm";
